    "and     t2, t0, t1\n"
    "beqz    t2, 1f\n"
    "li      t3, 0xe0500008\n"
    "ld      t4, 0(t3)\n"
    "andi    t4, t4, 1\n"
    "beqz    t4, 1f\n"
    "li      t5, 0xe0500040\n"
    "li      t6, %[cmd]\n"
    "sd      t6, 0(t5)\n"
    "2:\n"
    "li      t2, 0xe0500080\n"
    "ld      t3, 0(t2)\n"
    "li      t4, %[mask]\n"
    "and     t3, t3, t4\n"
    "li      t5, %[running]\n"
    "beq     t3, t5, 2b\n"
    "1:\n"
    :
    : [cmd] "K"(CCTL_L2_WBINVAL_ALL),
      [mask] "K"(CCTL_ST_MASK),
      [running] "K"(CCTL_L2_ST_RUNNING)
  );
#endif
}

__attribute__((used)) static inline void sim_syscall(uint64_t dev,
                                                       uint64_t cmd,
                                                       uint64_t tohost)
{
  volatile uint64_t* command = (volatile uint64_t*) TOHOST_CMD_REG;
  uint64_t tohost_cmd = TOHOST_CMD(dev, cmd, tohost);
  flush_all_dcache();
  *command = tohost_cmd;
  asm volatile("fence rw,rw");
}

__attribute__((used)) static inline uint64_t frontend_syscall(uint64_t n,
                                                               uint64_t a0,
                                                               uint64_t a1,
                                                               uint64_t a2,
                                                               uint64_t a3,
                                                               uint64_t a4,
                                                               uint64_t a5,
                                                               uint64_t a6)
{
  magicmem[0] = n;
  magicmem[1] = a0;
  magicmem[2] = a1;
  magicmem[3] = a2;
  magicmem[4] = a3;
  magicmem[5] = a4;
  magicmem[6] = a5;
  magicmem[7] = a6;
  sim_syscall(0, 0, (uintptr_t) magicmem);
  return magicmem[0];
}

