273	        if (v->fpr[i]) has_fp = 1;
274	    }
275	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
276	
277	    s.mstatus  = read_reg64(v->mstatus);
278	    s.mepc     = read_reg64(v->mepc);
279	    s.mtvec    = read_reg64(v->mtvec);
280	    s.mcause   = read_reg64(v->mcause);
281	    s.mtval    = read_reg64(v->mtval);
282	    s.mscratch = read_reg64(v->mscratch);
283	    s.medeleg  = read_reg64(v->medeleg);
284	    s.mideleg  = read_reg64(v->mideleg);
285	    s.mip      = read_reg64(v->mip);
286	    s.mie      = read_reg64(v->mie);
287	    s.mcycle   = read_reg64(v->mcycle);
288	    s.minstret = minstret_override ? minstret_override
289	                                   : read_reg64(v->minstret);
290	    s.satp     = read_reg64(v->satp);
291	
292	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
293	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
294	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
295	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
296	
297	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
298	    // bounds the per-register byte count copied into vreg[]. The policy
299	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
300	    // handle truthiness so we don't conflate "stub missing vlenb" with
301	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
302	    s.vstart = read_reg64(v->vstart);
303	    s.vxsat  = read_reg64(v->vxsat);
304	    s.vxrm   = read_reg64(v->vxrm);
305	    s.vcsr   = read_reg64(v->vcsr);
306	    s.vtype  = read_reg64(v->vtype);
307	    s.vl     = read_reg64(v->vl);
308	    s.vlenb  = read_reg64(v->vlenb);
309	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
310	                       || v->vtype || v->vl);
311	    if (!has_other_v) {
312	        for (int i = 0; i < 32; i++)
313	            if (v->vreg[i]) { has_other_v = 1; break; }
314	    }
315	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
316	        v->vlenb != NULL, has_other_v, s.vlenb);
317	    if (vpol == HYBRID_V_DRAIN_ABORT) {
318	        fprintf(stderr,
319	                "hybrid_handoff: stub advertised V CSRs/regs but not vlenb; "
320	                "refusing to drain partial V state\n");
321	        exit(2);
322	    }
323	    if (vpol == HYBRID_V_DRAIN_OK) {
324	        s.flags |= HYBRID_FLAG_V;
325	        size_t bytes = s.vlenb < HYBRID_VLEN_BYTES_MAX
326	                     ? (size_t) s.vlenb
327	                     : (size_t) HYBRID_VLEN_BYTES_MAX;
328	        for (int i = 0; i < 32; i++)
329	            (void) read_reg_bytes(v->vreg[i],
330	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
331	                                  bytes);
332	    }
333	
334	    if (write_state_atomic(&s, outfile_path) != 0) {
335	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
336	        exit(2);
337	    }
338	    fprintf(stderr,
339	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
340	            outfile_path, s.pc);
341	}
342	
343	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
344	// as the vsim resume point, and exit 200.
345	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
346	{
347	    // F14: suppress the atexit drain path now that we have a real trigger.
348	    drained_already = 1;
349	    drain_state_to_file(vcpu_idx, resume_pc, 0);
350	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
351	    // Distinguishes drain from workload completion (0) so the orchestrator
352	    // can decide the next spawn.
353	    exit(200);
354	}
355	
356	// Marker sites. The marker is an architectural NOP, so the pre-execution
357	// state equals the post-retire state and the window resumes AFTER it
358	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
359	// the exec callback can lag the actual current insn when V instructions
360	// retire just before the trigger -- TCG defers PC writes for performance).
361	static void on_handoff(unsigned int vcpu_idx, void *udata)
362	{
363	    const HandoffSite *site = (const HandoffSite *) udata;
364	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
365	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
366	}
367	
368	// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
369	// executes, and the boundary insn is real user code (unlike a marker NOP):
370	// the drained state must resume AT the boundary so the insn executes inside
371	// the vsim window rather than on neither leg. (Skipping it corrupts the
372	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
373	// set and the first vector op of the window faults.)
374	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
375	{
376	    const HandoffSite *site = (const HandoffSite *) udata;
377	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
378	    handoff_drain(vcpu_idx, site->vaddr);
379	}
380	
381	// F14: per-insn tick. Increments a global counter every retired insn so the
382	// drain-at-exit path can report a true retired-insn total (independent of
383	// QEMU's PMU semantics).
384	static void on_count_tick(unsigned int vcpu_idx, void *udata)
385	{
386	    (void) vcpu_idx;
387	    (void) udata;
388	    atexit_insn_count++;
389	}
390	
391	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
392	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
393	// still set and qemu_plugin_read_register works. If any other trigger
394	// already drained, return immediately (drained_already guards against
395	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
396	// use _exit() to skip the rest of the atexit chain.
397	static void on_atexit(qemu_plugin_id_t id, void *udata)
398	{
399	    (void) id;
400	    (void) udata;
401	    if (drained_already) return;
402	    if (!drain_at_exit_mode) return;
403	    // pc=0 is a positive marker that the atexit path drained (no trigger).
404	    drain_state_to_file(0, 0, atexit_insn_count);
405	    fflush(stderr);
406	    _exit(200);
407	}
408	
409	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
410	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
411	// returns the lag-free post-trigger PC (same property as the CSR path).
412	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
413	{
414	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
415	    if (++v->icount_retired < icount_target) return;
416	    on_handoff_boundary(vcpu_idx, udata);
417	}
418	
419	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
420	// pointer; that mapping is stable across calls because bbv_emit_assign_id
421	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
422	// flushes a slice row when the per-slice counter saturates.
423	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
424	{
425	    (void) vcpu_idx;
426	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
427	    bbv_emit_tick(bbv_emit, bb_id);
428	}
429	
430	// Per-insn tick for slice-consume mode (F11). Counts insns into the
431	// slice accumulator; on each slice boundary increments slice_consume_idx
432	// and resets the accumulator. Once slice_consume_idx exceeds the target
433	// slice index, drains via on_handoff at that same insn boundary. udata
434	// is the per-insn HandoffSite (allocated at translation time) so the
435	// post-trigger PC reaches on_handoff lag-free.
436	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
437	{
438	    if (++slice_consume_acc < bbv_slice_target) return;
439	    slice_consume_acc = 0;
440	    if (slice_consume_idx++ < slice_at_target) return;
441	    // After the post-increment above, slice_consume_idx == slice_at_target+1
442	    // (the count of fully retired slices). Log so the e2e test can verify
443	    // drain timing without relying on minstret (which is a cycle-counter
444	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
445	    fprintf(stderr,
446	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
447	            " target=%" PRIu64 ")\n",
448	            slice_consume_idx, slice_at_target);
449	    on_handoff_boundary(vcpu_idx, udata);
450	}
451	
452	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
453	{
454	    (void) id;
455	    size_t n = qemu_plugin_tb_n_insns(tb);
456	
457	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
458	    // TB-start vaddr). Same id is shared by every insn in the TB.
459	    uint64_t bb_id = 0;
460	    if (bbv_mode && n > 0) {
461	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
462	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
463	    }
464	
465	    for (size_t i = 0; i < n; i++) {
466	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
467	
468	        // F14 count tick: registered FIRST so the count is incremented
469	        // before any trigger callback can call exit(200). NO_REGS keeps
470	        // the per-insn cost minimal (a single uint64 add).
471	        if (drain_at_exit_mode) {
472	            qemu_plugin_register_vcpu_insn_exec_cb(
473	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
474	        }
475	
476	        // BBV callback is registered BEFORE icount so that if both modes
477	        // fire on the same insn (icount target == slice multiple), the
478	        // slice row is emitted before exit(200) is called.
479	        if (bbv_mode) {
480	            qemu_plugin_register_vcpu_insn_exec_cb(
481	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
482	                GUINT_TO_POINTER((guint) bb_id));
483	        }
484	
485	        // Slice-consume callback (F11). Registered after BBV so a BBV
486	        // row at the same boundary is flushed first; ordering vs icount
487	        // is irrelevant (both drain).
488	        if (slice_consume_mode) {
489	            HandoffSite *site = g_new0(HandoffSite, 1);
490	            site->kind  = HYBRID_HANDOFF_ENTER;
491	            site->vaddr = qemu_plugin_insn_vaddr(insn);
492	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
493	            qemu_plugin_register_vcpu_insn_exec_cb(
494	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
495	        }
496	
497	        if (icount_mode) {
498	            HandoffSite *site = g_new0(HandoffSite, 1);
499	            site->kind  = HYBRID_HANDOFF_ENTER;
500	            site->vaddr = qemu_plugin_insn_vaddr(insn);
501	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
502	            qemu_plugin_register_vcpu_insn_exec_cb(
503	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
504	        }
505	
506	        if (pc_mode) {
507	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
508	            // boundary (on_handoff_boundary), so the insn size is recorded
509	            // only for completeness.
510	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
511	            HandoffSite *site = g_new0(HandoffSite, 1);
512	            site->kind  = HYBRID_HANDOFF_ENTER;
513	            site->vaddr = qemu_plugin_insn_vaddr(insn);
514	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
515	            qemu_plugin_register_vcpu_insn_exec_cb(
516	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
517	            continue;
518	        }
519	
520	        // Marker-trigger mode (default).
521	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
522	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
523	        // exact, not an approximation.
524	        size_t sz = qemu_plugin_insn_size(insn);
525	        if (sz != 4) continue;
526	        uint32_t raw = 0;
527	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
528	            continue;
529	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
530	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
531	        HandoffSite *site = g_new0(HandoffSite, 1);
532	        site->kind  = kind;
533	        site->vaddr = qemu_plugin_insn_vaddr(insn);
534	        site->size  = (uint32_t) sz;
535	        qemu_plugin_register_vcpu_insn_exec_cb(
536	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
537	    }
538	}
539	
540	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
541	                                           const qemu_info_t *info,
542	                                           int argc, char **argv)
543	{
544	    (void) info;
545	    for (int i = 0; i < argc; i++) {
546	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
547	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
548	            outfile_path = g_strdup(tok[1]);
549	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
550	            char *endp = NULL;
551	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
552	            if (!endp || *endp != '\0') {
553	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
554	                        tok[1]);
555	                return -1;
556	            }
557	            enter_pc_arg = (uint64_t) v;
558	            pc_mode = 1;
559	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
560	            char *endp = NULL;
561	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
562	            if (!endp || *endp != '\0' || v == 0) {
563	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
564	                        tok[1]);
565	                return -1;
566	            }
567	            icount_target = (uint64_t) v;
568	            icount_mode = 1;
569	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
570	            bbv_out_path = g_strdup(tok[1]);
571	            bbv_mode = 1;
572	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
573	            char *endp = NULL;
574	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
575	            if (!endp || *endp != '\0' || v == 0) {
576	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
577	                        tok[1]);
578	                return -1;
579	            }
580	            bbv_slice_target = (uint64_t) v;
581	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
582	            char *endp = NULL;
583	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
584	            if (!endp || *endp != '\0') {
585	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
586	                        tok[1]);
587	                return -1;
588	            }
589	            slice_at_target = (uint64_t) v;
590	            slice_consume_mode = 1;
591	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
592	            // F14: any non-zero value enables. "1" is the canonical form
593	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
594	            // also enable -- the flag is a binary switch, not a count.
595	            char *endp = NULL;
596	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
597	            if (!endp || *endp != '\0') {
598	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
599	                        tok[1]);
600	                return -1;
601	            }
602	            drain_at_exit_mode = (v != 0);
603	        } else {
604	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
605	            return -1;
606	        }
607	    }
608	    if (!outfile_path) {
609	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
610	        return -1;
611	    }
612	    if (pc_mode) {
613	        fprintf(stderr,
614	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
615	                enter_pc_arg);
616	    }
617	    if (icount_mode) {
618	        fprintf(stderr,
619	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
620	                icount_target);
621	    }
622	    if (bbv_mode) {
623	        if (bbv_slice_target == 0) {
624	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
625	            return -1;
626	        }
627	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
628	        if (!bbv_emit) {
629	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
630	                    bbv_out_path);
631	            return -1;
632	        }
633	        fprintf(stderr,
634	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
635	                bbv_out_path, bbv_slice_target);
636	    }
637	    if (slice_consume_mode) {
638	        if (bbv_slice_target == 0) {
639	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
640	            return -1;
641	        }
642	        fprintf(stderr,
643	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
644	                " slice_at=%" PRIu64 "\n",
645	                bbv_slice_target, slice_at_target);
646	    }
647	    if (drain_at_exit_mode) {
648	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
649	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
650	    }
651	
652	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
653	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
654	    return 0;
655	}
