// andes-sim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
// and future backends). One C++20 binary that selects a model (fast / cycle
// / hybrid), resolves engines at runtime, and either passes through to a single
// engine or orchestrates a hybrid round-trip.
//
// This file owns argument dispatch only: parse the CLI, route to a command.
// Each subcommand below resolves to its handler as its feature lands (F1-F13);
// until then it stubs out, keeping the command surface stable.
#include <cstdio>
#include <cstdlib>
#include <exception>
#include <string>
#include <string_view>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "repo_root.hpp"

namespace andes_sim {
int cmd_list(const Cli& cli);
int cmd_doctor(const Cli& cli);
int cmd_build(const Cli& cli);
int cmd_run(const Cli& cli);
}  // namespace andes_sim

namespace {

using andes_sim::Cli;
using andes_sim::is_dev_mode;

// Each command's release tier decides where it shows in `--help`:
//   Release -- the finished, user-facing product surface (always listed).
//   Dev     -- developer tooling, listed only when ANDES_SIM_DEV is set.
//   Hidden  -- a stable dispatch slot for an unfinished ROADMAP feature; never
//              listed (explicit invocation still hits the "not yet implemented"
//              stub), so the product never advertises half-built work.
enum class Tier { Release, Dev, Hidden };

struct Subcommand {
  std::string_view name;
  std::string_view brief;
  Tier tier;
};

// The full command surface. Names are fixed from F0 so usage, dispatch, and
// tests are stable; handlers arrive feature by feature. The tier (above) keeps
// dev and unfinished commands out of the release `--help` (see print_usage).
// Listed release-first, then dev, then hidden -- dispatch is by name, so the
// order is purely the display order.
constexpr Subcommand kSubcommands[] = {
    {"run", "run one simulation (--model fast|cycle|hybrid)", Tier::Release},
    {"list", "list models|engines", Tier::Release},
    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)",
     Tier::Dev},
    {"test", "run the end-to-end suite", Tier::Dev},
    {"doctor", "check environment health", Tier::Dev},
    {"profile", "profile a workload into a basic-block vector", Tier::Hidden},
    {"cluster", "cluster a BBV into SimPoint phases", Tier::Hidden},
    {"archive", "snapshot a drained state into a replayable dir", Tier::Hidden},
    {"replay", "replay a snapshot", Tier::Hidden},
    {"estimate",
     "whole-program cycle estimate (run --model hybrid --trigger simpoint)",
     Tier::Hidden},
};

const Subcommand* find(std::string_view name) {
  for (const Subcommand& s : kSubcommands)
    if (s.name == name) return &s;
  return nullptr;
}

void print_command(std::FILE* out, const Subcommand& s) {
  std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
               s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
}

void print_usage(std::FILE* out) {
  std::fputs("usage: andes-sim <cmd> [args...]\n\n", out);
  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
             out);
  std::fputs("commands:\n", out);
  for (const Subcommand& s : kSubcommands)
    if (s.tier == Tier::Release) print_command(out, s);

  if (is_dev_mode()) {
    std::fputs("\ndeveloper commands:\n", out);
    for (const Subcommand& s : kSubcommands)
      if (s.tier == Tier::Dev) print_command(out, s);
  } else {
    std::fputs("\n(set ANDES_SIM_DEV=1 to show developer commands)\n", out);
  }
}

void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
  std::fprintf(out, "usage: andes-sim %.*s [args...]\n\n",
               static_cast<int>(sc.name.size()), sc.name.data());
  std::fprintf(out, "%.*s\n", static_cast<int>(sc.brief.size()), sc.brief.data());
  if (sc.name == "run") {
    std::fputs(
        "\nselection:\n"
        "  --model fast|cycle|hybrid          which composition to run\n"
        "  --engine <id>                      pick a specific engine "
        "(e.g. vsim:ax45mpv_premium)\n"
        "  --trigger marker|pc|icount            ROI delimiter (hybrid only)\n"
        "  --mem-size <spec>                  guest memory, e.g. 256M / 2G "
        "(max 2G; fast/hybrid)\n"
        "  -- <args...>                       forward everything after -- "
        "verbatim to the engine\n",
        out);
  } else if (sc.name == "list") {
    // fixtures lists internal test ELFs -- a developer target, shown only in
    // dev mode (the release product lists user-facing models + engines).
    std::fputs(is_dev_mode() ? "\ntargets: fixtures | models | engines\n"
                             : "\ntargets: models | engines\n",
               out);
  }
}

}  // namespace

int main(int argc, char** argv) {
  using namespace andes_sim;

  Cli cli = parse_cli(argc, argv);
  if (!cli.error.empty()) {
    std::fprintf(stderr, "andes-sim: %s\n", cli.error.c_str());
    return 2;
  }

  if (cli.subcommand.empty()) {  // no command, or top-level -h
    if (cli.help) {
      print_usage(stdout);
      return 0;
    }
    print_usage(stderr);
    return 2;
  }

  const Subcommand* sc = find(cli.subcommand);
  if (!sc) {
    std::fprintf(stderr, "andes-sim: unknown command '%s'\n\n",
                 cli.subcommand.c_str());
    print_usage(stderr);
    return 2;
  }

  if (cli.help) {
    print_subcommand_help(*sc, stdout);
    return 0;
  }

  if (cli.subcommand == "list") return cmd_list(cli);
  if (cli.subcommand == "doctor") return cmd_doctor(cli);
  if (cli.subcommand == "build") return cmd_build(cli);
  if (cli.subcommand == "run") return cmd_run(cli);

  // Remaining subcommands stub out until their feature lands. Resolve the repo
  // root so the discovery path stays live and observable.
  std::string root;
  try {
    root = repo_root().string();
  } catch (const std::exception& e) {
    root = std::string("<unknown: ") + e.what() + ">";
  }
  std::fprintf(stderr, "andes-sim %s: not yet implemented (repo root: %s)\n",
               cli.subcommand.c_str(), root.c_str());
  return 3;
}

// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDES_SIM_RUN_PLAN_HPP
#define ANDES_SIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
};

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. icount -> qemu
// `,icount=<qemu_icount>` / vsim `--hybrid-icount <vsim_icount>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = 200;        // drain success code (kExitHandoffToQemu)
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
};

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDES_SIM_RUN_PLAN_HPP

