// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "state.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

}  // namespace

LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err) {
  err.clear();
  LegTriggerArgs out;
  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv

  const bool fast = role == "fast-leg";
  const bool accurate = role == "accurate-leg";
  if (!fast && !accurate) return out;  // other roles carry no trigger args

  // Required-param lookup. A missing key is a caller bug; surface it (don't
  // throw) so plan_argvs can report which step failed.
  auto param = [&](const char* key) -> const std::string* {
    auto it = t.params.find(key);
    if (it == t.params.end()) {
      err = "trigger '" + t.kind + "' missing param '" + key + "'";
      return nullptr;
    }
    return &it->second;
  };

  if (t.kind == "pc") {
    if (fast) {
      if (const std::string* p = param("enter_pc"))
        out.plugin_suffix = ",enter_pc=" + *p;
    } else if (const std::string* p = param("exit_pc")) {
      out.extra = {"--hybrid-exit-pc", *p};
    }
    return out;
  }
  if (t.kind == "icount") {
    if (fast) {
      if (const std::string* p = param("qemu_icount"))
        out.plugin_suffix = ",icount=" + *p;
    } else if (const std::string* p = param("vsim_icount")) {
      out.extra = {"--hybrid-icount", *p};
    }
    return out;
  }

  err = "unknown trigger kind '" + t.kind + "'";
  return out;
}

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
  long vlen = 0;
  for (const Step& s : plan.steps)
    if (s.role == "accurate-leg")
      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
        if (e->vlen > 0) vlen = e->vlen;
  const std::string vlen_str = std::to_string(synced_vlen(vlen));

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    std::string trig_err;
    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
    if (!trig_err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + trig_err;
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
        {"vlen", vlen_str},
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
    // after the filled template (matches tests/e2e.sh's ordering).
    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
  std::string mmap_path = plan.mmap_path;
  const bool own_mmap = mmap_path.empty();
  if (own_mmap) {
    std::string err;
    mmap_path = allocate(plan.mem_size, err);
    if (mmap_path.empty()) {
      res.error = err;
      return res;
    }
  }

  // A private dir for the threaded drain files.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    if (own_mmap) ::unlink(mmap_path.c_str());
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = mmap_path;
  ctx.mem_size = plan.mem_size;
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else {
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = "plan step " + std::to_string(i) + ": expected exit " +
                    std::to_string(opts.expect_rc) + ", got " +
                    std::to_string(r.rc);
        break;
      }
      const StateFile sf = read_state_file(state_path(wd, i));
      if (!sf.ok()) {
        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
        break;
      }
      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out});
    }
  }

  fs::remove_all(wd, ec);
  if (own_mmap) ::unlink(mmap_path.c_str());
  return res;
}

}  // namespace andes_sim

// Translation-time capture of a handoff trigger insn. The QEMU TCG plugin
// allocates one of these per matched insn during vcpu_tb_trans and forwards
// the pointer as exec-callback userdata. compute_handoff_pc(site) returns
// the PC at which vsim should resume (i.e. the architectural PC immediately
// after the trigger insn retires).
//
// This indirection exists because qemu_plugin_read_register("pc") inside an
// exec callback returns a stale PC when V instructions retire just before
// the trigger -- TCG defers PC writes for performance and the gdbstub
// readback observes the lag. vaddr/size are deterministic at translate time
// (qemu_plugin_insn_vaddr/size), so vaddr+size is a lag-free post-trigger
// PC. Same predicate, two consumers: the plugin (C) and a doctest unit
// test (C++).
//
// Lifetime: sites are heap-allocated in vcpu_tb_trans and never freed --
// the plugin has no "TB invalidated" hook and trigger sites are bounded by
// the fixture's text (typically 1-2 marker insns).

#ifndef HYBRID_HANDOFF_SITE_H
#define HYBRID_HANDOFF_SITE_H

#include "hybrid/insn_match.h"

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct HandoffSite
{
  hybrid_handoff_kind kind;
  uint64_t            vaddr;
  uint32_t            size;
} HandoffSite;

static inline uint64_t compute_handoff_pc(const HandoffSite* site)
{
  return site->vaddr + (uint64_t) site->size;
}

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_HANDOFF_SITE_H

// Pattern recogniser for the magic handoff marker convention. The same
// predicate runs in two places: the QEMU TCG plugin (C) and the vsim PC
// pre-scan (C++).
//
// The markers are RISC-V HINT instructions: SLTI with rd=x0 discards its
// result, so it is an architectural NOP on every conforming core. Marker
// binaries therefore run unmodified on real silicon and on every engine
// (fast/cycle/hybrid) -- unlike the retired `csrwi 0x7C0` markers, where
// CSR 0x7C0 is MILMB on Andes cores and the exit marker enabled ILM at
// base 0, killing standalone runs. The 12-bit immediate carries the
// marker kind; rs1 is pinned to x0 so each marker is one exact 32-bit
// word. SLTI has no compressed form, so markers are always 4 bytes.

#ifndef HYBRID_INSN_MATCH_H
#define HYBRID_INSN_MATCH_H

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum
{
  HYBRID_HANDOFF_NONE  = 0,
  HYBRID_HANDOFF_ENTER = 1,  // slti x0, x0, 0x5A0
  HYBRID_HANDOFF_EXIT  = 2,  // slti x0, x0, 0x5A1
} hybrid_handoff_kind;

// slti x0, x0, imm: OP-IMM (0x13), funct3=010, rd=rs1=x0, imm[31:20].
#define HYBRID_MARKER_ENTER_INSN 0x5A002013u
#define HYBRID_MARKER_EXIT_INSN  0x5A102013u

// Returns true when `insn` is one of the two marker HINTs. On match,
// *out_kind is set to ENTER or EXIT.
static inline bool hybrid_match_handoff_insn(uint32_t insn,
                                             hybrid_handoff_kind* out_kind)
{
  if (insn == HYBRID_MARKER_ENTER_INSN) {
    *out_kind = HYBRID_HANDOFF_ENTER;
    return true;
  }
  if (insn == HYBRID_MARKER_EXIT_INSN) {
    *out_kind = HYBRID_HANDOFF_EXIT;
    return true;
  }
  return false;
}

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_INSN_MATCH_H

// andes-sim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andes-sim <cmd> [--model M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDES_SIM_CLI_HPP
#define ANDES_SIM_CLI_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --model fast|cycle|hybrid
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc|icount|simpoint
  std::string what;                       // --what <target> (build)
  // Hybrid trigger args (empty => cmd_run applies the default). pc boundaries
  // are a symbol name or 0x address; the icounts/sizes stay strings here and
  // are parsed where they are used.
  std::string pc_start;                   // --pc-start (trigger pc)
  std::string pc_end;                     // --pc-end   (trigger pc)
  std::string qemu_icount;                // --qemu-icount (trigger icount)
  std::string vsim_icount;                // --vsim-icount (trigger icount)
  std::string mem_size;                   // --mem-size (guest memory; --mmap-size is a hidden alias)
  std::string vsim_warmup_icount;         // --vsim-warmup-icount (vsim leg)
  std::string kanata;                     // --kanata <file> (marker/pc ROI trace)
  std::string objdump;                    // --objdump <file> (kanata labels)
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  bool help = false;                      // -h / --help (before `--`)
  bool dry_run = false;                   // --dry-run (build, run, test, ...)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_CLI_HPP

