1	// `andes-sim run --model fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <cstdio>
12	#include <filesystem>
13	#include <string>
14	
15	#include "cli.hpp"
16	#include "engine_descriptor.hpp"
17	#include "engine_registry.hpp"
18	#include "hybrid.hpp"
19	#include "models.hpp"
20	#include "plan.hpp"
21	#include "run_passthrough.hpp"
22	#include "run_plan.hpp"
23	#include "shm.hpp"
24	
25	namespace fs = std::filesystem;
26	
27	namespace andes_sim {
28	namespace {
29	
30	// Validate the lone-ELF positional shape the standalone models require: print
31	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
32	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
33	// spawns a --describe subprocess per Verilator build). `model` labels the error.
34	int check_one_elf(const Cli& cli, const char* model) {
35	  if (cli.positional.empty()) {
36	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
37	    return 2;
38	  }
39	  if (cli.positional.size() > 1) {
40	    std::fprintf(stderr,
41	                 "andes-sim run --model %s: unexpected argument '%s' "
42	                 "(engine args go after --)\n",
43	                 model, cli.positional[1].c_str());
44	    return 2;
45	  }
46	  return 0;
47	}
48	
49	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
50	// single ELF, then exec the resolved engine standalone with `extra` (model
51	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
52	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
53	// per-model differences -- which engine, and how it is selected -- are resolved
54	// by the caller; `model` here only labels the positional diagnostics.
55	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
56	                   const char* model,
57	                   const std::vector<std::string>& extra = {}) {
58	  if (int rc = check_one_elf(cli, model)) return rc;
59	  std::vector<std::string> args = extra;
60	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
61	  std::string err;
62	  int rc = run_passthrough(eng, "standalone", cli.positional[0], args, err);
63	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
64	  return rc;
65	}
66	
67	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
68	// only the built-in qemu descriptor, so it resolves that directly rather than
69	// discover_engines(), which would spawn a --describe subprocess per Verilator
70	// build only to discard them all here.
71	int run_fast(const Cli& cli) {
72	  // fast is QEMU-only; an explicit engine must name it.
73	  if (!cli.engine.empty() && cli.engine != "qemu") {
74	    std::fprintf(stderr,
75	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
76	                 cli.engine.c_str());
77	    return 2;
78	  }
79	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
80	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
81	  std::string err;
82	  const std::vector<std::string> mem = qemu_m_args(cli.mem_size, err);
83	  if (!err.empty()) {
84	    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
85	    return 2;
86	  }
87	  return run_standalone(cli, builtin_qemu(), "fast", mem);
88	}
89	
90	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
91	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
92	// engine's own output. Unlike fast, this must discover the Verilator build(s)
93	// to resolve the engine (explicit --engine, else the sole one).
94	int run_accurate(const Cli& cli) {
95	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
96	  // --describe subprocess per Verilator build only to fail on the argument.
97	  if (int rc = check_one_elf(cli, "cycle")) return rc;
98	  // --mem-size is validated but has nothing to size: the cycle engine always
99	  // models its full DRAM window. Say so instead of silently ignoring it.
100	  if (!cli.mem_size.empty()) {
101	    std::string se;
102	    if (parse_size(cli.mem_size, se); !se.empty()) {
103	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
104	                   se.c_str());
105	      return 2;
106	    }
107	    std::fprintf(stderr,
108	                 "[andes-sim] --mem-size: the cycle engine models its full "
109	                 "DRAM window; nothing to size\n");
110	  }
111	  Discovery disc = discover_engines();
112	  std::string err;
113	  const EngineDescriptor* eng =
114	      resolve_accurate_engine(disc.engines, cli.engine, err);
115	  if (!eng) {
116	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
117	    // Surface why an expected engine may be absent (failed --describe, etc.).
118	    for (const std::string& w : disc.warnings)
119	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
120	    return 2;
121	  }
122	  return run_standalone(cli, *eng, "cycle");
123	}
124	
125	// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
126	// handoff (no QEMU2). The trigger (marker|pc|icount) delimits the ROI; the cycle
127	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
128	// driver's tests/e2e.sh delegation with a single window-cycle line.
129	int run_hybrid(const Cli& cli) {
130	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
131	  auto fail = [](const std::string& msg) {
132	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
133	    return 2;
134	  };
135	
136	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
137	
138	  // Resolve to an absolute, existing path: a clean error beats a downstream
139	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
140	  std::error_code ec;
141	  const fs::path elf = fs::absolute(cli.positional[0], ec);
142	  if (ec || !fs::is_regular_file(elf, ec))
143	    return fail("ELF not found: " + cli.positional[0]);
144	  const std::string elf_path = elf.string();
145	
146	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
147	  // mistake fails fast without spawning a --describe per Verilator build.
148	  std::string err;
149	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
150	  if (!err.empty()) return fail(err);
151	
152	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
153	  if (!err.empty()) return fail(err);
154	
155	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
156	  if (!cli.mem_size.empty()) {
157	    std::string se;
158	    mem = parse_size(cli.mem_size, se);
159	    if (!se.empty()) return fail("--mem-size: " + se);
160	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
161	    // guest RAM here. Failing now beats allocating a huge mmap file first and
162	    // letting QEMU die late.
163	    if (mem > 2LL * 1024 * 1024 * 1024)
164	      return fail("--mem-size " + cli.mem_size +
165	                  " exceeds the AE350 DRAM window (2G max)");
166	  }
167	
168	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
169	  // or the sole cycle-accurate engine (reusing the F8 selector).
