}

auto check_hybrid_handoff() -> std::optional<int>
{
  if constexpr (!requires { cpu.get_committed_pc(); }) {
    return std::nullopt;
  } else {
    const auto committed = cpu.get_committed_pc();
    if (committed.empty()) return std::nullopt;
    for (const auto pc: committed[0]) {
      auto state = std::optional<hybrid_state_v1>{};
      if (hybrid_handoff_)
        state = hybrid_handoff_->on_retire(pc);
      else if (hybrid_icount_handoff_)
        state = hybrid_icount_handoff_->on_retire(pc);
      if (state) {
        // V-register merge: the fixture's vsim-phase epilogue is expected
        // to have run vse8.v v0..v31 to scratch RAM before the exit
        // trigger fired. Read those bytes back into state.vreg[] so the
        // drained handoff state carries vsim's actual V values, not
        // QEMU 1's stale snapshot.
        if ((state->flags & HYBRID_FLAG_V) != 0u) {
          hybrid::read_v_from_scratch(
            *state,
            std::span<const uint8_t>{platform.main_memory.data.data(),
                                     platform.main_memory.data.size()},
            platform.main_memory.region.base_address);
        }
        spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
                     pc, hybrid_state_path_);
        std::ofstream f(hybrid_state_path_, std::ios::binary);
        f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
        return hybrid::kExitHandoffToQemu;
      }
    }
    return std::nullopt;
  }
}

void enable_waveform(const std::string& waveform_filename)
{
  trace_.enable_waveform(cpu, waveform_filename);
}

void enable_pc_trace(const std::string& filename)
{
  trace_.enable_pc_trace(filename);
}

void disable_pc_trace() { trace_.disable_pc_trace(); }

void enable_kanata(const std::string& filename,
                   const std::string& objdump_file = "",
                   std::optional<kanata::LoopGate> gate = std::nullopt)
{
  trace_.enable_kanata(cpu, filename, objdump_file, gate);
}

void enable_clarity(const std::string& filename,
                    const std::string& objdump_file = "",
                    std::optional<kanata::LoopGate> gate = std::nullopt)
{
  trace_.enable_clarity(cpu, filename, objdump_file, gate);
}

// Auto-derive the kanata LoopGate from the active hybrid state:
//   start_pc = resume PC (from hybrid_input_state_->pc)
//   end_pc   = explicit_exit_pc when set (pc-mode -- the --hybrid-exit-pc
//              CLI value), otherwise the unique HYBRID_HANDOFF_EXIT PC
//              scanned by the CsrTrigger (csr-mode).
// Must be called AFTER apply_resume_from_qemu and enable_hybrid_handoff,
// so the resume PC and the CsrTrigger are populated.
void enable_kanata_roi(const std::string& filename,
                       const std::string& objdump_file,
                       std::optional<uint64_t> explicit_exit_pc)
{
  if (!hybrid_input_state_)
    throw std::runtime_error(
      "--kanata-roi requires --resume-from-qemu (no resume PC available)");
  if (!hybrid_handoff_)
    throw std::runtime_error(
      "--kanata-roi requires CSR or PC trigger mode "
      "(incompatible with --hybrid-icount)");
  const auto gate = hybrid::derive_roi_kanata_gate(
    hybrid_handoff_->trigger(), hybrid_input_state_->pc, explicit_exit_pc);
  spdlog::info(
    "kanata-roi: window start=0x{:x} end=0x{:x} (skip=0 record=1)",
    gate.start_pc, gate.end_pc);
  trace_.enable_kanata(cpu, filename, objdump_file, gate);

