1	// `andes-sim run --model fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <cstdio>
12	#include <filesystem>
13	#include <string>
14	
15	#include "cli.hpp"
16	#include "engine_descriptor.hpp"
17	#include "engine_registry.hpp"
18	#include "hybrid.hpp"
19	#include "models.hpp"
20	#include "plan.hpp"
21	#include "run_passthrough.hpp"
22	#include "run_plan.hpp"
23	#include "shm.hpp"
24	#include "state_diff.hpp"
25	
26	namespace fs = std::filesystem;
27	
28	namespace andes_sim {
29	namespace {
30	
31	// Validate the lone-ELF positional shape the standalone models require: print
32	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
33	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
34	// spawns a --describe subprocess per Verilator build). `model` labels the error.
35	int check_one_elf(const Cli& cli, const char* model) {
36	  if (cli.positional.empty()) {
37	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
38	    return 2;
39	  }
40	  if (cli.positional.size() > 1) {
41	    std::fprintf(stderr,
42	                 "andes-sim run --model %s: unexpected argument '%s' "
43	                 "(engine args go after --)\n",
44	                 model, cli.positional[1].c_str());
45	    return 2;
46	  }
47	  return 0;
48	}
49	
50	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
51	// single ELF, then exec the resolved engine standalone with `extra` (model
52	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
53	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
54	// per-model differences -- which engine, and how it is selected -- are resolved
55	// by the caller; `model` here only labels the positional diagnostics.
56	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
57	                   const char* model,
58	                   const std::vector<std::string>& extra = {}) {
59	  if (int rc = check_one_elf(cli, model)) return rc;
60	  std::vector<std::string> args = extra;
61	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
62	  std::string err;
63	  int rc = run_passthrough(eng, "standalone", cli.positional[0], args, err);
64	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
65	  return rc;
66	}
67	
68	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
69	// only the built-in qemu descriptor, so it resolves that directly rather than
70	// discover_engines(), which would spawn a --describe subprocess per Verilator
71	// build only to discard them all here.
72	int run_fast(const Cli& cli) {
73	  // fast is QEMU-only; an explicit engine must name it.
74	  if (!cli.engine.empty() && cli.engine != "qemu") {
75	    std::fprintf(stderr,
76	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
77	                 cli.engine.c_str());
78	    return 2;
79	  }
80	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
81	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
82	  std::string err;
83	  const std::vector<std::string> mem = qemu_m_args(cli.mem_size, err);
84	  if (!err.empty()) {
85	    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
86	    return 2;
87	  }
88	  return run_standalone(cli, builtin_qemu(), "fast", mem);
89	}
