91	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
92	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
93	// engine's own output. Unlike fast, this must discover the Verilator build(s)
94	// to resolve the engine (explicit --engine, else the sole one).
95	int run_accurate(const Cli& cli) {
96	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
97	  // --describe subprocess per Verilator build only to fail on the argument.
98	  if (int rc = check_one_elf(cli, "cycle")) return rc;
99	  // --mem-size is validated but has nothing to size: the cycle engine always
100	  // models its full DRAM window. Say so instead of silently ignoring it.
101	  if (!cli.mem_size.empty()) {
102	    std::string se;
103	    if (parse_size(cli.mem_size, se); !se.empty()) {
104	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
105	                   se.c_str());
106	      return 2;
107	    }
108	    std::fprintf(stderr,
109	                 "[andes-sim] --mem-size: the cycle engine models its full "
110	                 "DRAM window; nothing to size\n");
111	  }
112	  Discovery disc = discover_engines();
113	  std::string err;
114	  const EngineDescriptor* eng =
115	      resolve_accurate_engine(disc.engines, cli.engine, err);
116	  if (!eng) {
117	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
118	    // Surface why an expected engine may be absent (failed --describe, etc.).
119	    for (const std::string& w : disc.warnings)
120	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
121	    return 2;
122	  }
123	  return run_standalone(cli, *eng, "cycle");
124	}
