126	// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
127	// handoff (no QEMU2). The trigger (marker|pc|icount) delimits the ROI; the cycle
128	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
129	// driver's tests/e2e.sh delegation with a single window-cycle line.
130	int run_hybrid(const Cli& cli) {
131	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
132	  auto fail = [](const std::string& msg) {
133	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
134	    return 2;
135	  };
136	
137	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
138	
139	  // Resolve to an absolute, existing path: a clean error beats a downstream
140	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
141	  std::error_code ec;
142	  const fs::path elf = fs::absolute(cli.positional[0], ec);
143	  if (ec || !fs::is_regular_file(elf, ec))
144	    return fail("ELF not found: " + cli.positional[0]);
145	  const std::string elf_path = elf.string();
146	
147	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
148	  // mistake fails fast without spawning a --describe per Verilator build.
149	  std::string err;
150	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
151	  if (!err.empty()) return fail(err);
152	
153	  // --verify needs a boundary the oracle can arm on; the icount window's
154	  // off-by-one semantics differ between the legs (see verify_oracle.md).
155	  if (cli.verify && trig.kind != "marker" && trig.kind != "pc")
156	    return fail("--verify supports --trigger marker|pc");
157	
158	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
159	  if (!err.empty()) return fail(err);
160	
161	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
162	  if (!cli.mem_size.empty()) {
163	    std::string se;
164	    mem = parse_size(cli.mem_size, se);
165	    if (!se.empty()) return fail("--mem-size: " + se);
166	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
167	    // guest RAM here. Failing now beats allocating a huge mmap file first and
168	    // letting QEMU die late.
169	    if (mem > 2LL * 1024 * 1024 * 1024)
170	      return fail("--mem-size " + cli.mem_size +
171	                  " exceeds the AE350 DRAM window (2G max)");
172	  }
173	
174	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
175	  // or the sole cycle-accurate engine (reusing the F8 selector).
176	  Discovery disc = discover_engines();
177	  const EngineDescriptor* acc =
178	      resolve_accurate_engine(disc.engines, cli.engine, err);
179	  if (!acc) {
180	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", err.c_str());
181	    for (const std::string& w : disc.warnings)
182	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
183	    return 2;
184	  }
185	
186	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
187	  // cannot share architectural state with the rv64 fast leg).
188	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
189	
190	  Plan plan;
191	  plan.elf = elf_path;
192	  plan.mem_size = mem;
193	  Step qemu_step{"qemu", "fast-leg", trig};
194	  Step vsim_step{acc->id, "accurate-leg", trig};
195	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
196	  plan.steps = {qemu_step, vsim_step};
197	
198	  // Banner to stderr so the window-cycle result stands alone on stdout.
199	  // vlen is the synced value the fast leg inherits from the engine.
200	  std::fprintf(stderr,
201	               "[andes-sim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
202	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
203	               elf.stem().string().c_str());
204	
205	  const PlanResult r = run_plan(plan, disc.engines);
206	  if (!r.ok()) {
207	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", r.error.c_str());
208	    return 1;
209	  }
210	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
211	  // output, then anything the ROI wrote on vsim) belong to the user.
212	  for (const PhaseResult& p : r.phases)
213	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
214	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
215	  // vsim mcycle delta.
216	  const unsigned long long q_mc = r.phases[0].mcycle;
217	  const unsigned long long v_mc = r.phases[1].mcycle;
218	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
219	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
220	
221	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
222	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
223	  // halt pc, and diff the two drains in-process. The oracle plan gets its
224	  // own fresh mmap: reusing the main run's would boot the oracle on the
225	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
226	  // output was already relayed from the main run.
227	  if (cli.verify) {
228	    char pcbuf[32];
229	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
230	                  static_cast<unsigned long long>(r.phases[1].st.pc));
231	    Trigger vtrig;
232	    vtrig.kind = "verify-" + trig.kind;
233	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
234	    vtrig.params["drain_pc"] = pcbuf;
235	
236	    Plan vplan;
237	    vplan.elf = elf_path;
238	    vplan.mem_size = mem;
239	    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};
240	
241	    std::fprintf(stderr,
242	                 "[andes-sim] verify: oracle leg (pure QEMU drains at the ROI "
243	                 "exit, pc=%s)\n",
244	                 pcbuf);
245	    const PlanResult vr = run_plan(vplan, disc.engines);
246	    if (!vr.ok()) {
247	      std::fprintf(stderr, "andes-sim run --verify: %s\n", vr.error.c_str());
248	      return 1;
249	    }
250	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
251	    print_diff_report(d);
252	    if (!d.ok()) {
253	      std::fprintf(stderr,
254	                   "andes-sim run --verify: vsim drain diverges from the "
255	                   "QEMU oracle\n");
256	      return 1;
257	    }
258	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
259	  }
260	
261	  std::printf("PASS: --model hybrid --trigger %s (%s)\n", trig.kind.c_str(),
262	              elf.stem().string().c_str());
263	  return 0;
264	}
265	
266	}  // namespace
267	
268	int cmd_run(const Cli& cli) {
269	  if (cli.model.empty()) {
270	    std::fprintf(stderr,
271	                 "andes-sim run: --model fast|cycle|hybrid is required\n");
272	    return 2;
273	  }
274	  if (!find_model(cli.model)) {
275	    std::fprintf(stderr,
276	                 "andes-sim run: unknown model '%s' (want fast|cycle|hybrid)\n",
277	                 cli.model.c_str());
278	    return 2;
279	  }
280	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
281	  // composition has a second engine to check.
282	  if (cli.verify && cli.model != "hybrid") {
283	    std::fprintf(stderr,
284	                 "andes-sim run: --verify requires --model hybrid (the %s "
285	                 "model has nothing to cross-check)\n",
286	                 cli.model.c_str());
287	    return 2;
288	  }
289	  if (cli.model == "fast") return run_fast(cli);
290	  if (cli.model == "cycle") return run_accurate(cli);
291	  return run_hybrid(cli);  // model validated above; only hybrid remains
292	}
293	
294	}  // namespace andes_sim
