/* Tier-2 C-level handoff smoke test (2-phase: QEMU1 -> vsim).
 *
 * Phase 1 (QEMU1): printf via newlib stdio -> libgloss_vh -> semihosting,
 *   handled by QEMU. Then slti x0, x0,  0x5A0 -- plugin drains state.
 * Phase 2 (vsim):  empty body. Phase-2 rule (rt_c_helpers.h): no syscall
 *   may issue inside this span. vsim drains at slti x0, x0,  0x5A1 and exits 200.
 *
 * (The old phase-3 QEMU2 printf was removed with the QEMU2 leg.)
 */

#include "runtime/rt_c_helpers.h"
#include <stdio.h>

int main(void)
{
  printf("hello from QEMU1\n");
  fflush(stdout);

  enter_vsim();
  /* Phase 2: vsim. No syscalls. */
  exit_vsim();

  return 0;
}
---
/*
 * F14 fixture: small C program with NO ROI marker HINT anywhere.
 * Exits naturally via crt0 -> _exit (libgloss_vh semihosting EXIT).
 *
 * QEMU sees the semihosting EXIT and runs its atexit chain; the
 * hybrid_handoff plugin's `drain_at_exit=1` callback drains state and
 * _exit(200) so ./hsim.py estimate --icount 0 can read minstret as N_total.
 *
 * Loop is sized so the BBV profile pass at slice=1000 produces enough
 * rows for SimPoint --max-k 2 (>= 2 rows; we want >= 10 for safety).
 */
#include <stdio.h>

int main(void) {
    long acc = 0;
    for (long i = 0; i < 2000; i++) {
        acc += i * 3 + 7;
    }
    printf("no_trigger_exit acc=%ld\n", acc);
    return 0;
}

