32	// Validate the lone-ELF positional shape the standalone models require: print
33	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
34	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
35	// spawns a --describe subprocess per Verilator build). `model` labels the error.
36	int check_one_elf(const Cli& cli, const char* model) {
37	  if (cli.positional.empty()) {
38	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
39	    return 2;
40	  }
41	  if (cli.positional.size() > 1) {
42	    std::fprintf(stderr,
43	                 "andes-sim run --model %s: unexpected argument '%s' "
44	                 "(engine args go after --)\n",
45	                 model, cli.positional[1].c_str());
46	    return 2;
47	  }
48	  return 0;
49	}
50	
51	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
52	// single ELF, then exec the resolved engine standalone with `extra` (model
53	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
54	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
55	// per-model differences -- which engine, and how it is selected -- are resolved
56	// by the caller; `model` here only labels the positional diagnostics.
57	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
58	                   const char* model,
59	                   const std::vector<std::string>& extra = {}) {
60	  if (int rc = check_one_elf(cli, model)) return rc;
61	  std::vector<std::string> args = extra;
62	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
63	  std::string err;
64	  int rc = run_passthrough(eng, "standalone", cli.positional[0], args, err);
65	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
66	  return rc;
67	}
68	
69	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
70	// only the built-in qemu descriptor, so it resolves that directly rather than
71	// discover_engines(), which would spawn a --describe subprocess per Verilator
72	// build only to discard them all here.
73	int run_fast(const Cli& cli) {
74	  // fast is QEMU-only; an explicit engine must name it.
75	  if (!cli.engine.empty() && cli.engine != "qemu") {
76	    std::fprintf(stderr,
77	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
78	                 cli.engine.c_str());
79	    return 2;
80	  }
81	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
82	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
83	  std::string err;
84	  const std::vector<std::string> mem = qemu_m_args(cli.mem_size, err);
85	  if (!err.empty()) {
86	    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
87	    return 2;
88	  }
89	  return run_standalone(cli, builtin_qemu(), "fast", mem);
90	}
91	
92	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
93	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
94	// engine's own output. Unlike fast, this must discover the Verilator build(s)
95	// to resolve the engine (explicit --engine, else the sole one).
96	int run_accurate(const Cli& cli) {
97	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
98	  // --describe subprocess per Verilator build only to fail on the argument.
99	  if (int rc = check_one_elf(cli, "cycle")) return rc;
100	  // --mem-size is validated but has nothing to size: the cycle engine always
101	  // models its full DRAM window. Say so instead of silently ignoring it.
102	  if (!cli.mem_size.empty()) {
103	    std::string se;
104	    if (parse_size(cli.mem_size, se); !se.empty()) {
105	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
106	                   se.c_str());
107	      return 2;
108	    }
109	    std::fprintf(stderr,
110	                 "[andes-sim] --mem-size: the cycle engine models its full "
111	                 "DRAM window; nothing to size\n");
112	  }
113	  Discovery disc = discover_engines();
114	  std::string err;
115	  const EngineDescriptor* eng =
116	      resolve_accurate_engine(disc.engines, cli.engine, err);
117	  if (!eng) {
118	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
119	    // Surface why an expected engine may be absent (failed --describe, etc.).
120	    for (const std::string& w : disc.warnings)
121	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
122	    return 2;
123	  }
124	  return run_standalone(cli, *eng, "cycle");
125	}
