127	// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
128	// handoff (no QEMU2). The trigger (marker|pc|icount) delimits the ROI; the cycle
129	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
130	// driver's tests/e2e.sh delegation with a single window-cycle line.
131	int run_hybrid(const Cli& cli) {
132	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
133	  auto fail = [](const std::string& msg) {
134	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
135	    return 2;
136	  };
137	
138	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
139	
140	  // Resolve to an absolute, existing path: a clean error beats a downstream
141	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
142	  std::error_code ec;
143	  const fs::path elf = fs::absolute(cli.positional[0], ec);
144	  if (ec || !fs::is_regular_file(elf, ec))
145	    return fail("ELF not found: " + cli.positional[0]);
146	  const std::string elf_path = elf.string();
147	
148	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
149	  // mistake fails fast without spawning a --describe per Verilator build.
150	  std::string err;
151	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
152	  if (!err.empty()) return fail(err);
153	
154	  // --verify needs a boundary the oracle can arm on; the icount window's
155	  // off-by-one semantics differ between the legs (see verify_oracle.md).
156	  if (cli.verify && trig.kind != "marker" && trig.kind != "pc")
157	    return fail("--verify supports --trigger marker|pc");
158	
159	  // --cosim needs the same entry boundary for the oracle to arm on.
160	  if (cli.cosim && trig.kind != "marker" && trig.kind != "pc")
161	    return fail("--cosim supports --trigger marker|pc");
162	  unsigned long long cosim_interval = 10000;  // default per cosim_roi.md
163	  if (cli.cosim && !cli.cosim_interval.empty()) {
164	    char* end = nullptr;
165	    cosim_interval = std::strtoull(cli.cosim_interval.c_str(), &end, 10);
166	    if (!end || *end != '\0' || cli.cosim_interval.empty() ||
167	        cosim_interval == 0)
168	      return fail("--cosim-interval: want a positive integer, got '" +
169	                  cli.cosim_interval + "'");
170	  }
171	
172	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
173	  if (!err.empty()) return fail(err);
174	
175	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
176	  if (!cli.mem_size.empty()) {
177	    std::string se;
178	    mem = parse_size(cli.mem_size, se);
179	    if (!se.empty()) return fail("--mem-size: " + se);
180	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
181	    // guest RAM here. Failing now beats allocating a huge mmap file first and
182	    // letting QEMU die late.
183	    if (mem > 2LL * 1024 * 1024 * 1024)
184	      return fail("--mem-size " + cli.mem_size +
185	                  " exceeds the AE350 DRAM window (2G max)");
186	  }
187	
188	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
189	  // or the sole cycle-accurate engine (reusing the F8 selector).
190	  Discovery disc = discover_engines();
191	  const EngineDescriptor* acc =
192	      resolve_accurate_engine(disc.engines, cli.engine, err);
193	  if (!acc) {
194	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", err.c_str());
195	    for (const std::string& w : disc.warnings)
196	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
197	    return 2;
198	  }
199	
200	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
201	  // cannot share architectural state with the rv64 fast leg).
202	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
203	
204	  Plan plan;
205	  plan.elf = elf_path;
206	  plan.mem_size = mem;
207	  Step qemu_step{"qemu", "fast-leg", trig};
208	  Step vsim_step{acc->id, "accurate-leg", trig};
209	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
210	  if (cli.cosim) {
211	    // Orthogonal to the trigger: the vsim leg drains a resumable checkpoint
212	    // to <state_out>.ckpt<k> every N retires (run_plan reads them back).
213	    vsim_step.extra_args.push_back("--hybrid-cosim");
214	    vsim_step.extra_args.push_back(std::to_string(cosim_interval));
215	  }
216	  plan.steps = {qemu_step, vsim_step};
217	
218	  // Banner to stderr so the window-cycle result stands alone on stdout.
219	  // vlen is the synced value the fast leg inherits from the engine.
220	  std::fprintf(stderr,
221	               "[andes-sim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
222	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
223	               elf.stem().string().c_str());
224	
225	  const PlanResult r = run_plan(plan, disc.engines);
226	  if (!r.ok()) {
227	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", r.error.c_str());
228	    return 1;
229	  }
230	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
231	  // output, then anything the ROI wrote on vsim) belong to the user.
232	  for (const PhaseResult& p : r.phases)
233	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
234	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
235	  // vsim mcycle delta. Suppressed under --cosim: every checkpoint adds a DMI
236	  // halt + drain + resume to the vsim leg, so the delta no longer measures
237	  // the kernel (a --cosim run answers "where diverged", not "how many cycles").
238	  if (!cli.cosim) {
239	    const unsigned long long q_mc = r.phases[0].mcycle;
240	    const unsigned long long v_mc = r.phases[1].mcycle;
241	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
242	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
243	  }
244	
245	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
246	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
247	  // halt pc, and diff the two drains in-process. The oracle plan gets its
248	  // own fresh mmap: reusing the main run's would boot the oracle on the
249	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
250	  // output was already relayed from the main run.
251	  if (cli.verify) {
252	    char pcbuf[32];
253	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
254	                  static_cast<unsigned long long>(r.phases[1].st.pc));
255	    Trigger vtrig;
256	    vtrig.kind = "verify-" + trig.kind;
257	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
258	    vtrig.params["drain_pc"] = pcbuf;
259	
260	    Plan vplan;
261	    vplan.elf = elf_path;
262	    vplan.mem_size = mem;
263	    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};
264	
265	    std::fprintf(stderr,
266	                 "[andes-sim] verify: oracle leg (pure QEMU drains at the ROI "
267	                 "exit, pc=%s)\n",
268	                 pcbuf);
269	    const PlanResult vr = run_plan(vplan, disc.engines);
270	    if (!vr.ok()) {
271	      std::fprintf(stderr, "andes-sim run --verify: %s\n", vr.error.c_str());
272	      return 1;
273	    }
274	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
275	    print_diff_report(d);
276	    if (!d.ok()) {
277	      std::fprintf(stderr,
278	                   "andes-sim run --verify: vsim drain diverges from the "
279	                   "QEMU oracle\n");
280	      return 1;
281	    }
282	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
283	  }
284	
285	  // --cosim (cosim_roi F4, default off, dev): re-run the ELF on pure QEMU
286	  // with the plugin draining at the vsim checkpoints' retire deltas, then
287	  // diff checkpoint k against checkpoint k and the final drains. minstret is
288	  // restored from the entry state on resume, so `checkpoint.minstret -
289	  // entry.minstret` is the exact post-entry retire count -- both engines
290	  // sample the SAME architectural points, and the first mismatching window
291	  // brackets the divergence. Fresh mmap for the oracle (clean memory);
292	  // stdout dropped (already relayed from the main run).
293	  if (cli.cosim) {
294	    const unsigned long long m0 = r.phases[0].st.minstret;
295	    const std::vector<hybrid_state_v1>& vck = r.phases[1].checkpoints;
296	    std::vector<unsigned long long> deltas;
297	    std::string counts;
298	    for (const hybrid_state_v1& c : vck) {
299	      const unsigned long long d = c.minstret - m0;
300	      if (d == 0 || (!deltas.empty() && d <= deltas.back())) {
301	        std::fprintf(stderr,
302	                     "andes-sim run --cosim: non-ascending checkpoint "
303	                     "minstret deltas (vsim leg corrupt?)\n");
304	        return 1;
305	      }
306	      deltas.push_back(d);
307	      counts += std::to_string(d) + ":";
308	    }
309	    const unsigned long long df = r.phases[1].st.minstret - m0;
310	    if (df == 0 || (!deltas.empty() && df <= deltas.back())) {
311	      std::fprintf(stderr,
312	                   "andes-sim run --cosim: final minstret delta does not "
313	                   "extend the checkpoints (vsim leg corrupt?)\n");
314	      return 1;
315	    }
316	    counts += std::to_string(df);
317	
318	    Trigger ctrig;
319	    ctrig.kind = "cosim-" + trig.kind;
320	    if (trig.kind == "pc") ctrig.params["enter_pc"] = trig.params.at("enter_pc");
321	    ctrig.params["counts"] = counts;
322	
323	    Plan cplan;
324	    cplan.elf = elf_path;
325	    cplan.mem_size = mem;
326	    cplan.steps = {Step{"qemu", "fast-leg", ctrig}};
327	
328	    std::fprintf(stderr,
329	                 "[andes-sim] cosim: oracle leg (pure QEMU, %zu checkpoint(s) "
330	                 "+ final at retire deltas %s)\n",
331	                 vck.size(), counts.c_str());
332	    const PlanResult cr = run_plan(cplan, disc.engines);
333	    if (!cr.ok()) {
334	      std::fprintf(stderr, "andes-sim run --cosim: %s\n", cr.error.c_str());
335	      return 1;
336	    }
337	    const std::vector<hybrid_state_v1>& ock = cr.phases[0].checkpoints;
338	    if (ock.size() != vck.size()) {
339	      std::fprintf(stderr,
340	                   "andes-sim run --cosim: oracle wrote %zu checkpoint(s), "
341	                   "vsim wrote %zu\n",
342	                   ock.size(), vck.size());
343	      return 1;
344	    }
345	    for (size_t k = 0; k < vck.size(); ++k) {
346	      const DiffReport d = diff_states(ock[k], vck[k]);
347	      if (!d.ok()) {
348	        print_diff_report(d);
349	        std::fprintf(stderr,
350	                     "[cosim] FAIL: divergence in window %zu (retires "
351	                     "%llu..%llu after entry)\n",
352	                     k + 1, k == 0 ? 0ULL : deltas[k - 1], deltas[k]);
353	        return 1;
354	      }
355	    }
356	    const DiffReport fd = diff_states(cr.phases[0].st, r.phases[1].st);
357	    if (!fd.ok()) {
358	      print_diff_report(fd);
359	      std::fprintf(stderr,
360	                   "[cosim] FAIL: divergence in the final window (retires "
361	                   "%llu..%llu after entry)\n",
362	                   deltas.empty() ? 0ULL : deltas.back(), df);
363	      return 1;
364	    }
365	    std::printf("[cosim] PASS: %zu checkpoint(s) + final state match the "
366	                "QEMU oracle (interval %llu, %llu ROI retires)\n",
367	                vck.size(), cosim_interval, df);
368	  }
369	
370	  std::printf("PASS: --model hybrid --trigger %s (%s)\n", trig.kind.c_str(),
371	              elf.stem().string().c_str());
372	  return 0;
373	}
374	
375	}  // namespace
376	
377	int cmd_run(const Cli& cli) {
378	  if (cli.model.empty()) {
379	    std::fprintf(stderr,
