// `andes-sim run --model fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
// and `cycle` (a cycle-accurate engine, from reset): each resolves its
// engine, then hands off to transparent passthrough -- the ELF plus everything
// after `--` becomes the engine's own command line, run with inherited stdio,
// no timeout, and the exit code propagated, so a gdbstub / monitor /
// semihosting console all behave as if the engine were invoked directly.
// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
// window-cycle figure (the vsim mcycle delta).
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <string>

#include "cli.hpp"
#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "hybrid.hpp"
#include "models.hpp"
#include "plan.hpp"
#include "run_passthrough.hpp"
#include "run_plan.hpp"
#include "shm.hpp"
#include "state_diff.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Validate the lone-ELF positional shape the standalone models require: print
// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
// can reject a missing/extra ELF BEFORE paying for engine discovery (which
// spawns a --describe subprocess per Verilator build). `model` labels the error.
int check_one_elf(const Cli& cli, const char* model) {
  if (cli.positional.empty()) {
    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andes-sim run --model %s: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 model, cli.positional[1].c_str());
    return 2;
  }
  return 0;
}

// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
// single ELF, then exec the resolved engine standalone with `extra` (model
// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
// args verbatim (inherit stdio, no timeout, propagate exit code). The only
// per-model differences -- which engine, and how it is selected -- are resolved
// by the caller; `model` here only labels the positional diagnostics.
int run_standalone(const Cli& cli, const EngineDescriptor& eng,
                   const char* model,
                   const std::vector<std::string>& extra = {}) {
  if (int rc = check_one_elf(cli, model)) return rc;
  std::vector<std::string> args = extra;
  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
  std::string err;
  int rc = run_passthrough(eng, "standalone", cli.positional[0], args, err);
  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
  return rc;
}

// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
// only the built-in qemu descriptor, so it resolves that directly rather than
// discover_engines(), which would spawn a --describe subprocess per Verilator
// build only to discard them all here.
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != "qemu") {
    std::fprintf(stderr,
                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
  // default injected). It precedes the post-`--` args, so a user's own -m wins.
  std::string err;
  const std::vector<std::string> mem = qemu_m_args(cli.mem_size, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andes-sim run --model fast: %s\n", err.c_str());
    return 2;
  }
  return run_standalone(cli, builtin_qemu(), "fast", mem);
}

// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
// no --resume-from-qemu), transparent passthrough -- cycles surface in the
// engine's own output. Unlike fast, this must discover the Verilator build(s)
// to resolve the engine (explicit --engine, else the sole one).
int run_accurate(const Cli& cli) {
  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
  // --describe subprocess per Verilator build only to fail on the argument.
  if (int rc = check_one_elf(cli, "cycle")) return rc;
  // --mem-size is validated but has nothing to size: the cycle engine always
  // models its full DRAM window. Say so instead of silently ignoring it.
  if (!cli.mem_size.empty()) {
    std::string se;
    if (parse_size(cli.mem_size, se); !se.empty()) {
      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
                   se.c_str());
      return 2;
    }
    std::fprintf(stderr,
                 "[andes-sim] --mem-size: the cycle engine models its full "
                 "DRAM window; nothing to size\n");
  }
  Discovery disc = discover_engines();
  std::string err;
  const EngineDescriptor* eng =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!eng) {
    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
    // Surface why an expected engine may be absent (failed --describe, etc.).
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
    return 2;
  }
  return run_standalone(cli, *eng, "cycle");
}

// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
// handoff (no QEMU2). The trigger (marker|pc|icount) delimits the ROI; the cycle
// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
// driver's tests/e2e.sh delegation with a single window-cycle line.
int run_hybrid(const Cli& cli) {
  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
  auto fail = [](const std::string& msg) {
    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
    return 2;
  };

  if (int rc = check_one_elf(cli, "hybrid")) return rc;

  // Resolve to an absolute, existing path: a clean error beats a downstream
  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
  std::error_code ec;
  const fs::path elf = fs::absolute(cli.positional[0], ec);
  if (ec || !fs::is_regular_file(elf, ec))
    return fail("ELF not found: " + cli.positional[0]);
  const std::string elf_path = elf.string();

  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
  // mistake fails fast without spawning a --describe per Verilator build.
  std::string err;
  const Trigger trig = hybrid_trigger(cli, elf_path, err);
  if (!err.empty()) return fail(err);

  // --verify needs a boundary the oracle can arm on; the icount window's
  // off-by-one semantics differ between the legs (see verify_oracle.md).
  if (cli.verify && trig.kind != "marker" && trig.kind != "pc")
    return fail("--verify supports --trigger marker|pc");

  // --cosim needs the same entry boundary for the oracle to arm on.
  if (cli.cosim && trig.kind != "marker" && trig.kind != "pc")
    return fail("--cosim supports --trigger marker|pc");
  unsigned long long cosim_interval = 10000;  // default per cosim_roi.md
  if (cli.cosim && !cli.cosim_interval.empty()) {
    char* end = nullptr;
    cosim_interval = std::strtoull(cli.cosim_interval.c_str(), &end, 10);
    if (!end || *end != '\0' || cli.cosim_interval.empty() ||
        cosim_interval == 0)
      return fail("--cosim-interval: want a positive integer, got '" +
                  cli.cosim_interval + "'");
  }

  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
  if (!err.empty()) return fail(err);

  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
  if (!cli.mem_size.empty()) {
    std::string se;
    mem = parse_size(cli.mem_size, se);
    if (!se.empty()) return fail("--mem-size: " + se);
    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
    // guest RAM here. Failing now beats allocating a huge mmap file first and
    // letting QEMU die late.
    if (mem > 2LL * 1024 * 1024 * 1024)
      return fail("--mem-size " + cli.mem_size +
                  " exceeds the AE350 DRAM window (2G max)");
  }

  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
  // or the sole cycle-accurate engine (reusing the F8 selector).
  Discovery disc = discover_engines();
  const EngineDescriptor* acc =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!acc) {
    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", err.c_str());
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
    return 2;
  }

  // ISA sync: both legs must agree on the base ISA width (rv32 engines
  // cannot share architectural state with the rv64 fast leg).
  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);

  Plan plan;
  plan.elf = elf_path;
  plan.mem_size = mem;
  Step qemu_step{"qemu", "fast-leg", trig};
  Step vsim_step{acc->id, "accurate-leg", trig};
  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
  if (cli.cosim) {
    // Orthogonal to the trigger: the vsim leg drains a resumable checkpoint
    // to <state_out>.ckpt<k> every N retires (run_plan reads them back).
    vsim_step.extra_args.push_back("--hybrid-cosim");
    vsim_step.extra_args.push_back(std::to_string(cosim_interval));
  }
  plan.steps = {qemu_step, vsim_step};

  // Banner to stderr so the window-cycle result stands alone on stdout.
  // vlen is the synced value the fast leg inherits from the engine.
  std::fprintf(stderr,
               "[andes-sim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
               elf.stem().string().c_str());

  const PlanResult r = run_plan(plan, disc.engines);
  if (!r.ok()) {
    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", r.error.c_str());
    return 1;
  }
  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
  // output, then anything the ROI wrote on vsim) belong to the user.
  for (const PhaseResult& p : r.phases)
    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
  // vsim mcycle delta. Suppressed under --cosim: every checkpoint adds a DMI
  // halt + drain + resume to the vsim leg, so the delta no longer measures
  // the kernel (a --cosim run answers "where diverged", not "how many cycles").
  if (!cli.cosim) {
    const unsigned long long q_mc = r.phases[0].mcycle;
    const unsigned long long v_mc = r.phases[1].mcycle;
    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
  }

  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
  // with the plugin draining at the ROI exit boundary, sampling at vsim's
  // halt pc, and diff the two drains in-process. The oracle plan gets its
  // own fresh mmap: reusing the main run's would boot the oracle on the
  // hybrid run's leftover memory. Its stdout is dropped -- the program's
  // output was already relayed from the main run.
  if (cli.verify) {
    char pcbuf[32];
    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
                  static_cast<unsigned long long>(r.phases[1].st.pc));
    Trigger vtrig;
    vtrig.kind = "verify-" + trig.kind;
    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
    vtrig.params["drain_pc"] = pcbuf;

    Plan vplan;
    vplan.elf = elf_path;
    vplan.mem_size = mem;
    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};

    std::fprintf(stderr,
                 "[andes-sim] verify: oracle leg (pure QEMU drains at the ROI "
                 "exit, pc=%s)\n",
                 pcbuf);
    const PlanResult vr = run_plan(vplan, disc.engines);
    if (!vr.ok()) {
      std::fprintf(stderr, "andes-sim run --verify: %s\n", vr.error.c_str());
      return 1;
    }
    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
    print_diff_report(d);
    if (!d.ok()) {
      std::fprintf(stderr,
                   "andes-sim run --verify: vsim drain diverges from the "
                   "QEMU oracle\n");
      return 1;
    }
    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
  }

  // --cosim (cosim_roi F4, default off, dev): re-run the ELF on pure QEMU
  // with the plugin draining at the vsim checkpoints' retire deltas, then
  // diff checkpoint k against checkpoint k and the final drains. minstret is
  // restored from the entry state on resume, so `checkpoint.minstret -
  // entry.minstret` is the exact post-entry retire count -- both engines
  // sample the SAME architectural points, and the first mismatching window
  // brackets the divergence. Fresh mmap for the oracle (clean memory);
  // stdout dropped (already relayed from the main run).
  if (cli.cosim) {
    const unsigned long long m0 = r.phases[0].st.minstret;
    const std::vector<hybrid_state_v1>& vck = r.phases[1].checkpoints;
    std::vector<unsigned long long> deltas;
    std::string counts;
    for (const hybrid_state_v1& c : vck) {
      const unsigned long long d = c.minstret - m0;
      if (d == 0 || (!deltas.empty() && d <= deltas.back())) {
        std::fprintf(stderr,
                     "andes-sim run --cosim: non-ascending checkpoint "
                     "minstret deltas (vsim leg corrupt?)\n");
        return 1;
      }
      deltas.push_back(d);
      counts += std::to_string(d) + ":";
    }
    const unsigned long long df = r.phases[1].st.minstret - m0;
    if (df == 0 || (!deltas.empty() && df <= deltas.back())) {
      std::fprintf(stderr,
                   "andes-sim run --cosim: final minstret delta does not "
                   "extend the checkpoints (vsim leg corrupt?)\n");
      return 1;
    }
    counts += std::to_string(df);

    Trigger ctrig;
    ctrig.kind = "cosim-" + trig.kind;
    if (trig.kind == "pc") ctrig.params["enter_pc"] = trig.params.at("enter_pc");
    ctrig.params["counts"] = counts;

    Plan cplan;
    cplan.elf = elf_path;
    cplan.mem_size = mem;
    cplan.steps = {Step{"qemu", "fast-leg", ctrig}};

    std::fprintf(stderr,
                 "[andes-sim] cosim: oracle leg (pure QEMU, %zu checkpoint(s) "
                 "+ final at retire deltas %s)\n",
                 vck.size(), counts.c_str());
    const PlanResult cr = run_plan(cplan, disc.engines);
    if (!cr.ok()) {
      std::fprintf(stderr, "andes-sim run --cosim: %s\n", cr.error.c_str());
      return 1;
    }
    const std::vector<hybrid_state_v1>& ock = cr.phases[0].checkpoints;
    if (ock.size() != vck.size()) {
      std::fprintf(stderr,
                   "andes-sim run --cosim: oracle wrote %zu checkpoint(s), "
                   "vsim wrote %zu\n",
                   ock.size(), vck.size());
      return 1;
    }
    for (size_t k = 0; k < vck.size(); ++k) {
      const DiffReport d = diff_states(ock[k], vck[k]);
      if (!d.ok()) {
        print_diff_report(d);
        std::fprintf(stderr,
                     "[cosim] FAIL: divergence in window %zu (retires "
                     "%llu..%llu after entry)\n",
                     k + 1, k == 0 ? 0ULL : deltas[k - 1], deltas[k]);
        return 1;
      }
    }
    const DiffReport fd = diff_states(cr.phases[0].st, r.phases[1].st);
    if (!fd.ok()) {
      print_diff_report(fd);
      std::fprintf(stderr,
                   "[cosim] FAIL: divergence in the final window (retires "
                   "%llu..%llu after entry)\n",
                   deltas.empty() ? 0ULL : deltas.back(), df);
      return 1;
    }
    std::printf("[cosim] PASS: %zu checkpoint(s) + final state match the "
                "QEMU oracle (interval %llu, %llu ROI retires)\n",
                vck.size(), cosim_interval, df);
  }

  std::printf("PASS: --model hybrid --trigger %s (%s)\n", trig.kind.c_str(),
              elf.stem().string().c_str());
  return 0;
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andes-sim run: --model fast|cycle|hybrid is required\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andes-sim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
  // composition has a second engine to check.
  if (cli.verify && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andes-sim run: --verify requires --model hybrid (the %s "
                 "model has nothing to cross-check)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.cosim && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andes-sim run: --cosim requires --model hybrid (the %s "
                 "model has nothing to cross-check)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.cosim && cli.verify) {
    std::fprintf(stderr,
                 "andes-sim run: --verify and --cosim are exclusive (--cosim "
                 "already cross-checks the final state)\n");
    return 2;
  }
  if (!cli.cosim && !cli.cosim_interval.empty()) {
    std::fprintf(stderr, "andes-sim run: --cosim-interval requires --cosim\n");
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);
  if (cli.model == "cycle") return run_accurate(cli);
  return run_hybrid(cli);  // model validated above; only hybrid remains
}

}  // namespace andes_sim

// andes-sim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andes-sim <cmd> [--model M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDES_SIM_CLI_HPP
#define ANDES_SIM_CLI_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --model fast|cycle|hybrid
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc|icount|simpoint
  std::string what;                       // --what <target> (build)
  // Hybrid trigger args (empty => cmd_run applies the default). pc boundaries
  // are a symbol name or 0x address; the icounts/sizes stay strings here and
  // are parsed where they are used.
  std::string pc_start;                   // --pc-start (trigger pc)
  std::string pc_end;                     // --pc-end   (trigger pc)
  std::string qemu_icount;                // --qemu-icount (trigger icount)
  std::string vsim_icount;                // --vsim-icount (trigger icount)
  std::string mem_size;                   // --mem-size (guest memory; --mmap-size is a hidden alias)
  std::string vsim_warmup_icount;         // --vsim-warmup-icount (vsim leg)
  std::string kanata;                     // --kanata <file> (marker/pc ROI trace)
  std::string objdump;                    // --objdump <file> (kanata labels)
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  std::string cosim_interval;             // --cosim-interval (run --cosim)
  bool help = false;                      // -h / --help (before `--`)
  bool dry_run = false;                   // --dry-run (build, run, test, ...)
  bool verify = false;                    // --verify (run --model hybrid)
  bool cosim = false;                     // --cosim (run --model hybrid, dev)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_CLI_HPP

// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
//
// A Plan is a list of Steps; each Step names an engine (by id, resolved against
// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
// order, threads the drained hybrid_state_v1 file forward, and returns each
// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
// mcycle.
#ifndef ANDES_SIM_PLAN_HPP
#define ANDES_SIM_PLAN_HPP

#include <map>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// The ROI delimiter for a step. `kind` is marker|pc|icount|simpoint; `params`
// carries kind-specific values (e.g. icount=N, enter_pc, exit_pc) that F9 maps
// onto trigger args. F6 only exercises the default marker case (no params).
struct Trigger {
  std::string kind;
  std::map<std::string, std::string> params;
};

// One leg of a plan: which engine, which invoke role, under which trigger.
// `extra_args` are verbatim tokens appended after the filled template and the
// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
// leg's --vsim-warmup-icount / --kanata), which are orthogonal to the trigger.
struct Step {
  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
  Trigger trigger;
  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
};

// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
// every leg so memory threads through.
struct Plan {
  std::string elf;          // path to the ELF every leg launches
  long long mem_size = 0;   // shared-mmap size in bytes
  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
  std::vector<Step> steps;
};

// What one drain step measured (read back from its state file), plus the
// leg's captured stdout -- the guest program's own output (UART/semihosting)
// rides the engine's stdout and must flow through to the user. `st` is the
// full drained record (verify_oracle F4: run --verify diffs the vsim drain
// against the oracle leg's in-process, after run_plan removed the files).
struct PhaseResult {
  unsigned long long mcycle = 0;
  unsigned long long minstret = 0;
  std::string out;
  hybrid_state_v1 st{};
  // cosim_roi F4: in-ROI checkpoint drains (`<state_out>.ckpt<k>`, k from 1),
  // read back in order before run_plan removes the workdir. Empty unless the
  // leg ran with checkpointing enabled.
  std::vector<hybrid_state_v1> checkpoints{};
};

// Aggregate outcome. `error` empty => every step matched its expected exit and
// drained a valid state file; `phases` then holds one entry per step in order.
struct PlanResult {
  std::string error;
  std::vector<PhaseResult> phases;
  bool ok() const { return error.empty(); }
};

}  // namespace andes_sim

#endif  // ANDES_SIM_PLAN_HPP

// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDES_SIM_RUN_PLAN_HPP
#define ANDES_SIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
};

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. icount -> qemu
// `,icount=<qemu_icount>` / vsim `--hybrid-icount <vsim_icount>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = 200;        // drain success code (kExitHandoffToQemu)
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
};

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDES_SIM_RUN_PLAN_HPP

