191	    res.error = "plan has no steps";
192	    return res;
193	  }
194	
195	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
196	  std::string mmap_path = plan.mmap_path;
197	  const bool own_mmap = mmap_path.empty();
198	  if (own_mmap) {
199	    std::string err;
200	    mmap_path = allocate(plan.mem_size, err);
201	    if (mmap_path.empty()) {
202	      res.error = err;
203	      return res;
204	    }
205	  }
206	
207	  // A private dir for the threaded drain files.
208	  std::error_code ec;
209	  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
210	  std::string tmpl = workdir.string();
211	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
212	  tbuf.push_back('\0');
213	  const char* made = ::mkdtemp(tbuf.data());
214	  if (!made) {
215	    if (own_mmap) ::unlink(mmap_path.c_str());
216	    res.error = "failed to create plan work dir";
217	    return res;
218	  }
219	  const std::string wd = made;
220	
221	  RuntimeCtx ctx;
222	  ctx.mmap_path = mmap_path;
223	  ctx.mem_size = plan.mem_size;
224	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
225	
226	  std::string err;
227	  const std::vector<std::vector<std::string>> argvs =
228	      plan_argvs(plan, engines, wd, ctx, err);
229	  if (!err.empty()) {
230	    res.error = err;
231	  } else {
232	    for (size_t i = 0; i < argvs.size(); ++i) {
233	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
234	      if (r.spawn_failed) {
235	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
236	        break;
237	      }
238	      if (r.timed_out) {
239	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
240	                    std::to_string(opts.timeout_ms) + " ms";
241	        break;
242	      }
243	      if (r.rc != opts.expect_rc) {
244	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
245	                    std::to_string(opts.expect_rc) + ", got " +
246	                    std::to_string(r.rc);
247	        break;
248	      }
249	      const StateFile sf = read_state_file(state_path(wd, i));
250	      if (!sf.ok()) {
251	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
252	        break;
253	      }
254	      // cosim checkpoints (`<state_out>.ckpt<k>`): read them back now, in
255	      // order, before the workdir teardown below deletes the files.
256	      std::vector<hybrid_state_v1> ckpts;
257	      for (size_t k = 1;; ++k) {
258	        const std::string p =
259	            state_path(wd, i) + ".ckpt" + std::to_string(k);
260	        if (!fs::exists(p, ec)) break;
261	        const StateFile cf = read_state_file(p);
262	        if (!cf.ok()) {
263	          res.error = "plan step " + std::to_string(i) + ": checkpoint " +
264	                      std::to_string(k) + ": " + cf.error;
265	          break;
266	        }
267	        ckpts.push_back(cf.st);
268	      }
269	      if (!res.error.empty()) break;
270	      res.phases.push_back(
271	          {sf.st.mcycle, sf.st.minstret, r.out, sf.st, std::move(ckpts)});
272	    }
273	  }
274	
275	  fs::remove_all(wd, ec);
276	  if (own_mmap) ::unlink(mmap_path.c_str());
277	  return res;
