99	    // Program Buffer LAST -- after every architectural read above -- so the
100	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
101	    // cannot corrupt the values already captured. The simulator's
102	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
103	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
104	    if (input.flags & HYBRID_FLAG_V)
