135	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
136	      // Scratch GPRs back to the drained architectural values.
137	      write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
138	      write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
139	      write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
140	    }
