104	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
105	{
106	  hybrid_state_v1 s{};
107	  s.magic = HYBRID_STATE_MAGIC;
108	  s.version = HYBRID_STATE_VERSION;
109	  s.flags = HYBRID_FLAG_RV64;
110	  s.pc = pc;
111	  s.priv = 3;
112	  s.gpr[10] = x10;
113	  return s;
114	}
