116	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
117	  -> std::vector<uint32_t>
118	{
119	  std::vector<uint32_t> values;
120	  for (const auto& op : ops)
121	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
122	      values.push_back(op.value);
123	  return values;
124	}
