583	    if (!vstart_cmd_idx && op.kind == DmiOp::Kind::Write && op.reg == kCommand
584	        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x008))
585	      vstart_cmd_idx = i;
586	  }
587	  REQUIRE(vsetvl_pb_idx.has_value());
588	  REQUIRE(vstart_cmd_idx.has_value());
589	  CHECK(*vsetvl_pb_idx < *vstart_cmd_idx);
590	}
591	
592	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
593	          "before the architectural V-CSR restore and counter restore")
594	{
595	  RecordingBus bus;
596	  bus.dmstatus_value = (1u << 9) | (1u << 17);
597	
598	  auto s = rv64_state(0x80001000, 0);
599	  s.flags  |= HYBRID_FLAG_V;
600	  s.vlenb  = 64;
601	  s.vl     = 16;
602	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
603	  s.vstart = 7;
604	
605	  hybrid::ResumeDriver driver(bus);
606	  driver.resume(s);
607	
608	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
609	  std::vector<int> missing;
610	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
611	  for (uint16_t v = 0; v < 32; ++v) {
612	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
613	    std::optional<std::size_t> at;
614	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
615	      const auto& op = bus.ops[i];
616	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
617	          && op.value == want) { at = i; break; }
618	    }
619	    if (!at) { missing.push_back(v); continue; }
620	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
621	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
622	  }
623	  CHECK(missing.empty());
624	  REQUIRE(first_vle_idx.has_value());
625	  REQUIRE(last_vle_idx.has_value());
626	
627	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
628	  //     first and last register.
629	  auto x7_gpa_staged = [&](uint64_t gpa) {
630	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
631	      const auto& op = bus.ops[i];
632	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
633	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
634	          && ((op.value >> 16) & 1u)) {
635	        const auto& d0 = bus.ops[i - 2];
636	        const auto& d1 = bus.ops[i - 1];
637	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
638	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
639	          return true;
640	      }
641	    }
642	    return false;
643	  };
644	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa));
645	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa + 31ull * HYBRID_VLEN_BYTES_MAX));
646	
647	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
648	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
649	  //     (so the vle8.v insns cannot pollute the resumed counters).
650	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
651	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
652	    const auto& op = bus.ops[i];
653	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
654	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
655	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
656	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
657	  }
658	  REQUIRE(vstart_cmd_idx.has_value());
659	  REQUIRE(mcycle_cmd_idx.has_value());
660	  CHECK(*last_vle_idx < *vstart_cmd_idx);
661	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
662	}
663	
664	TEST_CASE("B4: resume with HYBRID_FLAG_FP and drained FS=Off still writes "
665	          "mstatus with FS != Off so FPR abstract writes are accepted")
666	{
667	  RecordingBus bus;
668	  bus.dmstatus_value = (1u << 9) | (1u << 17);
669	
670	  auto s = rv64_state(0x80001000, 0);
671	  s.flags  |= HYBRID_FLAG_FP;
672	  s.mstatus = 0;                  // FS = 00 (Off)
673	
674	  hybrid::ResumeDriver driver(bus);
675	  driver.resume(s);
676	
677	  // Find the abstract write that targets mstatus (regno = 0x300) and verify
678	  // FS (bits 14:13) was forced non-zero. The drained mstatus has FS=Off but
679	  // the hart needs FS != Off to accept abstract FPR writes; the gate must
680	  // OR in FS=Initial without altering the wire-format state.mstatus.
681	  std::optional<uint32_t> mstatus_low32;
682	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
683	    const auto& op = bus.ops[i];
684	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
685	        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x300)
686	        && ((op.value >> 16) & 1u)) {
687	      REQUIRE(i >= 2);
688	      mstatus_low32 = bus.ops[i - 2].value;
689	      break;
690	    }
691	  }
692	  REQUIRE(mstatus_low32.has_value());
693	  CHECK((*mstatus_low32 & 0x6000u) != 0u);
694	}
695	
696	TEST_CASE("B4: resume with HYBRID_FLAG_V and drained VS=Off still writes "
697	          "mstatus with VS != Off so V-CSR abstract writes are accepted")
698	{
699	  RecordingBus bus;
700	  bus.dmstatus_value = (1u << 9) | (1u << 17);
701	
702	  auto s = rv64_state(0x80001000, 0);
703	  s.flags  |= HYBRID_FLAG_V;
704	  s.mstatus = 0;                  // VS = 00 (Off)
705	
706	  hybrid::ResumeDriver driver(bus);
707	  driver.resume(s);
708	
709	  std::optional<uint32_t> mstatus_low32;
710	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
711	    const auto& op = bus.ops[i];
712	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
713	        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x300)
714	        && ((op.value >> 16) & 1u)) {
715	      REQUIRE(i >= 2);
716	      mstatus_low32 = bus.ops[i - 2].value;
717	      break;
718	    }
719	  }
720	  REQUIRE(mstatus_low32.has_value());
721	  CHECK((*mstatus_low32 & 0x600u) != 0u);
722	}
