724	TEST_CASE("resume throws when V-data sweep Program Buffer execution fails")
725	{
726	  // B1 regression: exec_progbuf used to return bool and four call sites
727	  // silently dropped the result. The very first PB exec inside resume() for a
728	  // V-state is the pb_v_data_sweep vsetvl (program_buffer.hpp:164); arming
729	  // fail_next_pb_exec makes that exec raise sticky cmderr, and the throw must
730	  // propagate through pb_v_data_sweep -> ResumeDriver::resume.
731	  RecordingBus bus;
732	  bus.dmstatus_value = (1u << 9) | (1u << 17);
733	  bus.fail_next_pb_exec = true;
734	
735	  auto s = rv64_state(0x80001000, 0);
736	  s.flags |= HYBRID_FLAG_V;
737	  s.vlenb = 16;
738	  s.vl    = 8;
739	  s.vtype = 0xC1;
740	
741	  hybrid::ResumeDriver driver(bus);
742	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
743	}
