745	TEST_CASE("resume without HYBRID_FLAG_V: no vsetvl PB instruction issued")
746	{
747	  RecordingBus bus;
748	  bus.dmstatus_value = (1u << 9) | (1u << 17);
749	
750	  hybrid::ResumeDriver driver(bus);
751	  driver.resume(rv64_state(0x80001000, 0));  // no HYBRID_FLAG_V
752	
753	  const uint32_t expected_vsetvl = hybrid::encode_vsetvl(0, 5, 6);
754	  bool found_vsetvl_pb = false;
755	  for (const auto& op : bus.ops)
756	    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
757	        && op.value == expected_vsetvl)
758	      found_vsetvl_pb = true;
759	  CHECK_FALSE(found_vsetvl_pb);
