#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
// Version 2 (L11): vreg[] widened from 64 to 128 bytes per register, which
// shifts every field after it. Readers reject version-1 files loudly (all
// three consumers check magic + version + size) instead of mis-parsing them.
#define HYBRID_STATE_VERSION 2u

#define HYBRID_FLAG_RV64 (1u << 0)
#define HYBRID_FLAG_FP   (1u << 1)
#define HYBRID_FLAG_V    (1u << 2)

// VLEN upper bound, in bytes: 256 covers the supported engine range
// VLEN 128..2048 (L11). This is the wire-format span per vector register;
// the LIVE width is the runtime `vlenb` field below, so one struct layout
// serves every engine config and the legs never disagree on offsets. A
// producer whose vlenb exceeds this ceiling must refuse to drain (see
// hybrid_v_drain_policy) rather than truncate.
#define HYBRID_VLEN_BYTES_MAX 256

// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
#define HYBRID_PMP_CFG_NUM  16
#define HYBRID_PMP_ADDR_NUM 64

// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
// unnecessary and would force unaligned access codegen. Layout is locked by
// the static_asserts in state_abi_check.h.
struct hybrid_state_v1 {
  uint32_t magic;
  uint32_t version;
  uint32_t flags;
  uint32_t hart_id;
  uint64_t pc;
  uint64_t priv;  // 0=U, 1=S, 3=M

  uint64_t gpr[32];
  uint64_t fpr[32];

  uint64_t mstatus;
  uint64_t mepc;
  uint64_t mtvec;
  uint64_t mcause;
  uint64_t mtval;
  uint64_t mscratch;
  uint64_t medeleg;
  uint64_t mideleg;
  uint64_t mip;
  uint64_t mie;
  uint64_t mcycle;
  uint64_t minstret;
  uint64_t satp;

  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];

  uint64_t vstart;
  uint64_t vtype;
  uint64_t vl;
  uint64_t vlenb;
  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
  uint64_t vxsat;
  uint64_t vxrm;
  uint64_t vcsr;

  // F13: warmup-window snapshot of cycle/instret counters, captured K insns
  // after vsim entry. Drain-only metadata; ResumeDriver never restores them.
  // Both zero when --vsim-warmup-icount=0 or the workload exited inside the
  // warmup window. Consumes 16 bytes from the original 232-byte reserved tail.
  uint64_t mcycle_at_measure_start;
  uint64_t minstret_at_measure_start;

  // L20: FP control/status -- frm[7:5] | fflags[4:0], live when
  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
  // re-read by StateDrain. Pre-L20 state files carry 0 here (reserved bytes
  // are written as zero), which reads back as the reset value (RNE, no
  // flags) -- exactly the old behavior, so no version bump.
  uint64_t fcsr;

  uint8_t  reserved[208];  // zero-initialise on write; 256 - 3*8 (vxsat/vxrm/vcsr) - 2*8 (warmup) - 8 (fcsr)
};

#ifdef __cplusplus
}  // extern "C"
#endif

#include "hybrid/state_abi_check.h"

#endif  // HYBRID_STATE_ABI_H

// Compile-time layout lock for hybrid_state_v1. The ABI is a wire contract,
// so any offset or size drift must break every consumer at compile time.

#ifndef HYBRID_STATE_ABI_CHECK_H
#define HYBRID_STATE_ABI_CHECK_H

#include "hybrid/state_abi.h"

// C++20 has static_assert; C11+ has _Static_assert. Pick the one that exists.
#ifndef __cplusplus
#  define static_assert _Static_assert
#endif

static_assert(offsetof(struct hybrid_state_v1, magic)    == 0,    "magic@0");
static_assert(offsetof(struct hybrid_state_v1, version)  == 4,    "version@4");
static_assert(offsetof(struct hybrid_state_v1, flags)    == 8,    "flags@8");
static_assert(offsetof(struct hybrid_state_v1, hart_id)  == 12,   "hart_id@12");
static_assert(offsetof(struct hybrid_state_v1, pc)       == 16,   "pc@16");
static_assert(offsetof(struct hybrid_state_v1, priv)     == 24,   "priv@24");

static_assert(offsetof(struct hybrid_state_v1, gpr)      == 32,   "gpr@32");
static_assert(offsetof(struct hybrid_state_v1, fpr)      == 288,  "fpr@288");

static_assert(offsetof(struct hybrid_state_v1, mstatus)  == 544,  "mstatus@544");
static_assert(offsetof(struct hybrid_state_v1, mepc)     == 552,  "mepc@552");
static_assert(offsetof(struct hybrid_state_v1, mtvec)    == 560,  "mtvec@560");
static_assert(offsetof(struct hybrid_state_v1, mcause)   == 568,  "mcause@568");
static_assert(offsetof(struct hybrid_state_v1, mtval)    == 576,  "mtval@576");
static_assert(offsetof(struct hybrid_state_v1, mscratch) == 584,  "mscratch@584");
static_assert(offsetof(struct hybrid_state_v1, medeleg)  == 592,  "medeleg@592");
static_assert(offsetof(struct hybrid_state_v1, mideleg)  == 600,  "mideleg@600");
static_assert(offsetof(struct hybrid_state_v1, mip)      == 608,  "mip@608");
static_assert(offsetof(struct hybrid_state_v1, mie)      == 616,  "mie@616");
static_assert(offsetof(struct hybrid_state_v1, mcycle)   == 624,  "mcycle@624");
static_assert(offsetof(struct hybrid_state_v1, minstret) == 632,  "minstret@632");
static_assert(offsetof(struct hybrid_state_v1, satp)     == 640,  "satp@640");

static_assert(offsetof(struct hybrid_state_v1, pmpcfg)   == 648,  "pmpcfg@648");
static_assert(offsetof(struct hybrid_state_v1, pmpaddr)  == 776,  "pmpaddr@776");

static_assert(offsetof(struct hybrid_state_v1, vstart)   == 1288, "vstart@1288");
static_assert(offsetof(struct hybrid_state_v1, vtype)    == 1296, "vtype@1296");
static_assert(offsetof(struct hybrid_state_v1, vl)       == 1304, "vl@1304");
static_assert(offsetof(struct hybrid_state_v1, vlenb)    == 1312, "vlenb@1312");
static_assert(offsetof(struct hybrid_state_v1, vreg)     == 1320, "vreg@1320");

// vreg occupies 32 * HYBRID_VLEN_BYTES_MAX bytes; vxsat/vxrm/vcsr follow
// it (consuming 24 bytes from the original 256-byte reserved trailer), then
// the F13 warmup snapshot pair consumes another 16 bytes; the reserved
// trailer keeps the total struct size unchanged.
static_assert(offsetof(struct hybrid_state_v1, vxsat)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX,
              "vxsat follows vreg[32 * HYBRID_VLEN_BYTES_MAX]");
static_assert(offsetof(struct hybrid_state_v1, vxrm)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 8,
              "vxrm follows vxsat");
static_assert(offsetof(struct hybrid_state_v1, vcsr)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 16,
              "vcsr follows vxrm");
static_assert(offsetof(struct hybrid_state_v1, mcycle_at_measure_start)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 24,
              "mcycle_at_measure_start follows vcsr (F13)");
static_assert(offsetof(struct hybrid_state_v1, minstret_at_measure_start)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 32,
              "minstret_at_measure_start follows mcycle_at_measure_start (F13)");
static_assert(offsetof(struct hybrid_state_v1, fcsr)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 40,
              "fcsr follows the F13 warmup snapshot pair (L20)");
static_assert(offsetof(struct hybrid_state_v1, reserved)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 48,
              "reserved follows fcsr");
static_assert(sizeof(struct hybrid_state_v1)
                == 1320 + 32 * HYBRID_VLEN_BYTES_MAX + 256,
              "hybrid_state_v1 total size unchanged "
              "(reserved shrinks 256->208 to absorb vxsat/vxrm/vcsr + warmup "
              "pair + fcsr)");

static_assert(HYBRID_VLEN_BYTES_MAX == 256,
              "HYBRID_VLEN_BYTES_MAX covers VLEN up to 2048 bits (L11); "
              "changing it shifts every offset after vreg and needs a "
              "version bump");
static_assert(HYBRID_PMP_CFG_NUM    == 16,  "pmpcfg slot count");
static_assert(HYBRID_PMP_ADDR_NUM   == 64,  "pmpaddr entry count");

#endif  // HYBRID_STATE_ABI_CHECK_H

// B7: doctest for the QEMU-plugin V-drain decision function.
//
// The plugin's V-state drain used to gate on `v->vlenb` (the register
// handle truthiness) AND `s.vlenb > 0`. The combination silently omits
// the V block whenever the stub advertises some V state but not vlenb,
// confusing "stub broke" with "V disabled at runtime". This test pins
// the four-case truth table: SKIP when no V at all, ABORT when partial,
// SKIP when V advertised but disabled (vlenb=0), OK otherwise.

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/state_abi.h"  // HYBRID_VLEN_BYTES_MAX (the L11 ceiling)
#include "hybrid/v_drain_policy.h"

TEST_CASE("no V advertised at all -> SKIP")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/0,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb missing but vtype/vl/etc advertised -> ABORT")
{
  // The "broken stub" case the original gate hid. Don't silently emit a
  // zero-filled V block: the resume side then restores garbage V state.
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_ABORT);
}

TEST_CASE("vlenb advertised but value=0 -> SKIP (V disabled at runtime)")
{
  // QEMU may expose the V feature in XML even when V is not enabled in
  // the CPU at runtime; vlenb then reads 0. Treat as "no V live".
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb advertised, value>0 -> OK")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_OK);
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/64)
        == HYBRID_V_DRAIN_OK);
}

TEST_CASE("L11: vlenb at the wire-format ceiling -> OK (VLEN 2048)")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/HYBRID_VLEN_BYTES_MAX)
        == HYBRID_V_DRAIN_OK);
}

TEST_CASE("L11: vlenb above the wire-format ceiling -> ABORT, not a "
          "silent clamp")
{
  // The old drain clamped the copy to HYBRID_VLEN_BYTES_MAX and dropped
  // the upper bytes of every V register without a word. Refuse instead:
  // the state file cannot represent this engine's V regfile.
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/HYBRID_VLEN_BYTES_MAX + 1)
        == HYBRID_V_DRAIN_ABORT);
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/2 * HYBRID_VLEN_BYTES_MAX)
        == HYBRID_V_DRAIN_ABORT);
}

TEST_CASE("vlenb advertised alone (no other V) is still ABORT-equivalent: "
          "policy treats vlenb-only as no V context")
{
  // Edge case: stub advertises vlenb but no other V regs. This is
  // unusual; treat as SKIP since we have no V data to actually drain.
  // (Documented behaviour, not a runtime failure mode QEMU emits.)
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/0,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_SKIP);
}

// Reads and validates a hybrid_state_v1 from a file produced by the QEMU
// plugin. Validation is the boundary check before any in-process JTAG poke.

#include "hybrid/state_abi.h"
#include "hybrid/state_loader.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include "test_tmpfile.hpp"

#include <filesystem>
#include <iterator>  // std::size

using namespace hybrid::test;

namespace {
auto good_state() -> hybrid_state_v1
{
  hybrid_state_v1 s{};
  s.magic = HYBRID_STATE_MAGIC;
  s.version = HYBRID_STATE_VERSION;
  s.flags = HYBRID_FLAG_RV64;
  s.hart_id = 0;
  s.pc = 0x80001000ULL;
  s.priv = 3;
  for (std::size_t i = 0; i < std::size(s.gpr); ++i)
    s.gpr[i] = 0xA0000000ULL + i;
  return s;
}
}  // namespace

TEST_CASE("load_state returns the struct verbatim from a valid file")
{
  const auto path = unique_tmp_path("loader_ok");
  const auto src = good_state();
  write_binary_file(path, &src, sizeof(src));

  hybrid::HybridState loaded = hybrid::load_state(path);
  CHECK(loaded.magic == HYBRID_STATE_MAGIC);
  CHECK(loaded.version == HYBRID_STATE_VERSION);
  CHECK(loaded.pc == 0x80001000ULL);
  CHECK(loaded.priv == 3);
  for (std::size_t i = 0; i < std::size(loaded.gpr); ++i)
    CHECK(loaded.gpr[i] == 0xA0000000ULL + i);
  std::filesystem::remove(path);
}

TEST_CASE("load_state rejects a missing file")
{
  const auto path = unique_tmp_path("loader_missing");
  std::filesystem::remove(path);
  CHECK_THROWS(hybrid::load_state(path));
}

TEST_CASE("load_state rejects a wrong-magic file")
{
  const auto path = unique_tmp_path("loader_magic");
  auto s = good_state();
  s.magic = 0xDEADBEEFu;
  write_binary_file(path, &s, sizeof(s));
  CHECK_THROWS(hybrid::load_state(path));
  std::filesystem::remove(path);
}

TEST_CASE("load_state rejects a wrong-version file")
{
  const auto path = unique_tmp_path("loader_version");
  auto s = good_state();
  s.version = HYBRID_STATE_VERSION + 1;
  write_binary_file(path, &s, sizeof(s));
  CHECK_THROWS(hybrid::load_state(path));
  std::filesystem::remove(path);
}

TEST_CASE("L11: load_state rejects a V state whose vlenb exceeds the "
          "wire-format ceiling")
{
  const auto path = unique_tmp_path("loader_vlenb");
  auto s = good_state();
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = HYBRID_VLEN_BYTES_MAX + 1;  // vreg[] cannot hold this register
  write_binary_file(path, &s, sizeof(s));
  CHECK_THROWS(hybrid::load_state(path));
  std::filesystem::remove(path);
}

TEST_CASE("L11: load_state accepts vlenb at the ceiling (VLEN 2048)")
{
  const auto path = unique_tmp_path("loader_vlenb_max");
  auto s = good_state();
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = HYBRID_VLEN_BYTES_MAX;
  write_binary_file(path, &s, sizeof(s));
  hybrid::HybridState loaded = hybrid::load_state(path);
  CHECK(loaded.vlenb == HYBRID_VLEN_BYTES_MAX);
  std::filesystem::remove(path);
}

TEST_CASE("load_state rejects a truncated file")
{
  const auto path = unique_tmp_path("loader_short");
  auto s = good_state();
  write_binary_file(path, &s, sizeof(s) - 16);
  CHECK_THROWS(hybrid::load_state(path));
  std::filesystem::remove(path);
}

